const RISK_REGISTER = [{"id":1,"activity":"Mobilization of workmen, tools and equipment","hazards":["Vehicle movements Loading and unloading of tools Personal injury/health defects Property/equipment damage Environmental impact"],"probability":4,"severity":3,"controls":["Induction to be conducted with all workforce to ensure that everyone is familiar with the work location and safety rules and regulations. Ensure that all workmen are adequately trained in the operation of tools and equipment. Provide safety awareness training to all personnel regarding potential hazards and safe work practices. Mandate the use of appropriate personal protective equipment, such as hard hats, safety glasses, gloves, and steel-toed boots, based on the nature of the work. Use secure and reliable transportation for the mobilization of tools and equipment. Ensure that tools and equipment are properly secured during transportation to prevent accidents. Implement proper traffic control measures if mobilization involves moving equipment on public roads. Control access to the work site to prevent unauthorized personnel from entering. Clearly mark designated paths for pedestrian and vehicle traffic. Use warning signs, flagman, and barricades to manage traffic safely. Develop and communicate emergency procedures, including evacuation plans and first aid protocols. Ensure that all personnel are familiar with emergency exits and assembly points. Consider environmental factors, such as weather conditions, and take appropriate precautions. Implement measures to prevent pollution and minimize the impact on the surrounding environment. Materials are handled with all safety measures while loading and unloading. Unloading area is forbidden for unauthorized entry if potential hazards exist. Assign competent supervisors to oversee the mobilization process and ensure adherence to safety procedures. Keep thorough records of safety inspections, equipment checks, and training sessions. Document any incidents or near-misses and use them as learning opportunities to improve safety measures. Comply as per ADOSH COP-44.0 & 2.0 & 34.0."],"revisedProbability":1,"revisedSeverity":3},{"id":2,"activity":"Survey Works","hazards":["Working nearby traffic Slips, trips, fall Personal injury/health defects, Property/equipment damage Environmental impact"],"probability":4,"severity":3,"controls":["Conduct pre-survey briefings to discuss the scope of work, potential hazards, and safety procedures. Keep a close eye on weather forecasts, especially in areas prone to extreme conditions, and take appropriate measures to protect workers from adverse weather. Ensure that surveying instruments and equipment are properly maintained and calibrated. Train workers on the safe operation of surveying tools. Establish reliable communication channels between team members Ensure all team members are aware of emergency procedures. Trained flagmen shall be assigned to control the Traffic where necessary. Crossing into severe traffic road is prohibited. Marking pin must be protected with warning tapes and rebar caps. Mandatory to be provided and worn by workers. Develop and communicate emergency procedures, including evacuation routes and first aid protocols."],"revisedProbability":1,"revisedSeverity":3},{"id":3,"activity":"Working with heavy machineries","hazards":["Vehicle/equipment Collision, hit by vehicles/equipment, Entanglement Personal injury/health defects, Property/equipment damage, Environmental impact"],"probability":4,"severity":3,"controls":["Ensure that operators are properly trained, certified, and competent in operating specific types of heavy machinery. Regularly update training to incorporate new safety procedures and technological advancements. Establish a pre-operational inspection routine for all heavy machinery to identify and address any mechanical issues before use. Encourage operators to report any malfunctions promptly. Mandate the use of appropriate PPE, including hard hats, high-visibility clothing, gloves, steel-toed boots, and hearing protection, depending on the nature of the work. Ensure that all heavy machinery is equipped with proper guards and safety devices to prevent contact with moving parts. Establish clear work zones and traffic patterns to separate pedestrians from moving machinery. Use barricades, signage, and designated walkways to guide personnel and prevent unauthorized access. Implement effective communication systems, such as hand signals, radios, or signaling devices, between operators and ground personnel. Establish an emergency communication protocol. Ensure operators have clear visibility from the operator's cabin. Use mirrors, cameras, or proximity sensors to eliminate blind spots. Ensure reverse alarm is installed and in working condition. Develop and enforce standardized operating procedures for each type of heavy machinery. Emphasize safe practices, including proper startup and shutdown procedures. Implement a regular maintenance schedule for heavy machinery to address wear and tear, lubrication, and other potential issues. Conduct thorough inspections before each use. Develop and communicate an emergency response plan that includes procedures for equipment malfunctions, accidents, and evacuation. Train operators on proper load handling techniques to prevent overloading and shifting during transport. Comply as per ADOSH COP-36.0"],"revisedProbability":1,"revisedSeverity":3},{"id":4,"activity":"Working with Mobile Scaffolding","hazards":["Falls from Height Tip-Overs and Collapses Entanglement Hazards Electrocution Contact with Objects and Overhead Obstacles Falling Objects Trapping Hazards Equipment Malfunction Hazardous Substances Poor Ground Conditions Weather Conditions Unauthorized Use"],"probability":4,"severity":3,"controls":["Ensure all operators are properly trained and certified to use the specific type of Mobile scaffolding. Training should include both theoretical knowledge and practical skills. Conduct daily or pre-use inspections to check for any defects or malfunctions in the mobile scaffolding, including controls, emergency descent mechanisms, guardrails, and personal fall protection equipment. Regularly maintain and service the mobile scaffolding according to the manufacturer's guidelines to ensure it's in safe working condition. Carry out a thorough risk assessment of the work area where the MEWP will be used. Identify hazards such as overhead obstacles, ground conditions, and nearby electrical lines. Plan the operation to minimize the risk of collision with pedestrians, vehicles, or structures. Choose a mobile scaffolding that is suitable for the task, considering factors such as height, reach, the weight capacity of the platform, and the ground conditions. Ensure that operators and occupants wear appropriate personal protective equipment (PPE), such as hard hats, safety harnesses, and lanyards attached to the mobile scaffolding when required. Use guardrails and ensure they are in place and secure before use. Follow the manufacturer’s operational instructions and guidelines for the mobile scaffolding. Keep body parts within the platform while operating the MEWP. Avoid overloading the platform beyond its weight capacity. Ensure that the body or stretch to regularize their blood circulation. A big screen/monitor must be provided to minimize the use of laptop with small screen as per the nature of the work. Use window blinds provided to control ambient light and screen reflection/glare. Ensure the computer screen is positioned at the right level, angle and height to eliminate or minimize glare onto the screen. Workstation must be sufficient of size for work and provide enough room to allow the employee to work. When using a mouse keep the arms level and the angle of the wrist to a minimum. Remember, as a general rule the things that are used the most should be kept close to the user to prevent overstretching. The immediate work environment should have sufficient space and an appropriate level of lighting. Temperature and humidity values must be maintained at optimum levels. Noise levels should be monitored and assessed accordingly. Move the chair close enough to the desk so that the keyboard can be reached out comfortably. Should always ensure there is enough room in front of the keyboard to rest the wrists and hands during pauses at work. When keying, keep the forearms horizontal and reduce the angle of the wrists to a minimum. Take adequate breaks to prevent continuous working and overexposure to screens: and ensure to do basic stretches and exercises to mitigate any risk to whole body due to musculoskeletal fatigue. Avoid sedentary work positions to avoid health issues. is on stable and level ground before elevating it. Be aware of weather conditions that could affect the operation, such as high winds. Be familiar with the mobile scaffolding’s emergency descent operations and procedures. Have a rescue plan in place in case of an emergency that leaves an operator stranded at height. Maintain clear communication between the operator in the MEWP and spotters or ground personnel. Use radios or signals as necessary. If working near or on public roads, implement traffic control measures to protect the mobile scaffolding and the operators from vehicle collisions. Utilize appropriate fall protection gear, especially when working at significant heights or when the mobile scaffolding does not have guardrails. When not in use, secure the mobile scaffolding to prevent unauthorized access or use. Always be aware of your surroundings when operating a mobile scaffolding. Look out for obstacles, ground conditions, and other workers."],"revisedProbability":1,"revisedSeverity":3},{"id":5,"activity":"Secant Piling Works","hazards":["Collapses and Cave-ins Falling from Heights Struck-by Injuries Crushing Injuries Noise and Vibration Dust and Airborne Contaminants Manual Handling Injuries Electrical Hazards Chemical Hazards Equipment Malfunction Environmental Hazards"],"probability":4,"severity":3,"controls":["Ensure the design of the secant pile wall accounts for soil conditions, groundwater levels, and the loads it will need to support. This requires input from experienced geotechnical engineers. Develop a detailed method statement outlining the sequence of works, specific safety measures, and how to deal with potential risks. Ensure all personnel, including operators, riggers, and spotters, are adequately trained in the specific operations they will perform, the equipment they will use, and the safety measures they must follow. Regularly inspect and maintain all equipment and machinery used for secant piling, including drilling rigs, to ensure they are in good working condition. Implement lockout/tag out procedures for equipment maintenance and repair. Erect barriers and signage to restrict access to the piling area, ensuring that only authorized personnel enter the work zone. Use instruments to monitor ground movements and vibrations during the piling process to prevent undermining adjacent structures. Adjust construction methods if excessive movement is detected. Implement measures to prevent runoff and sedimentation, especially in sites close to water bodies. Manage and dispose of waste materials according to local regulations. Develop and clearly communicate an emergency response plan that includes procedures for dealing with equipment failure, accidents, and injuries. Ensure all workers are familiar with the plan and conduct regular drills. Hold daily safety briefings to discuss the day's work, potential hazards, and safety measures. This ensures that all workers are informed of any changes or specific risks associated with the day’s activities. Require all site personnel to wear appropriate PPE, including hard hats, safety boots, high-visibility vests, gloves, and ear protection, depending on the specific hazards they may encounter."],"revisedProbability":1,"revisedSeverity":3},{"id":6,"activity":"Excavation works on Secant Piles","hazards":["Collapse or cave-in of excavation sides","Falls of persons or materials into the excavation","Contact with underground utilities or services","Hazardous atmosphere, oxygen deficiency or toxic gases","Plant and pedestrian interface","Water ingress and unstable ground conditions"],"probability":4,"severity":3,"controls":["Ensure that the design of the secant piles and the excavation plan are reviewed and approved by qualified engineers, taking into account the soil conditions and the intended load of the structure. Ensure that appropriate equipment is provided and used during excavation works. Provide safe means of access and egress for workers within the excavation area, such as ladders or stairways. Before excavation begins, locate and mark all underground utilities and services to prevent accidental strikes. Clearly communicate the hazards associated with the excavation work to all workers, including the risks of cave-ins, contact with utilities, and exposure to potentially hazardous atmospheres. Conduct atmospheric testing in excavations deeper than 4 feet to detect hazardous conditions such as toxic gases, oxygen deficiency, or flammable atmospheres. Take appropriate measures to ventilate or evacuate if hazardous conditions are detected. Have a competent person inspect the excavation, adjacent areas, and protective systems daily for signs of potential collapse or failure, and after any event that could have affected their stability. Continuously monitor the site for any changes in conditions that could affect the safety of the excavation and the secant pile construction. Develop and implement an emergency response plan that includes specific rescue procedures for the excavation site. Rescue Equipment: Ensure that appropriate rescue equipment is available and that workers are trained in its use."],"revisedProbability":1,"revisedSeverity":3},{"id":7,"activity":"Trial Pits","hazards":["Collapse of excavation Cave-in Fall of men and materials Slip, trip and falls Damaging the underground utilities, spark, explosion, fire, overflow Personal injury/health defects, Property/equipment damage, Environmental impact"],"probability":4,"severity":3,"controls":["Conduct a thorough risk assessment before commencing trial pit excavation. Identify potential hazards such as unstable soil, utilities, and the proximity of structures. Ensure that workers involved in trial pits are trained and competent in safe excavation practices. Designate a competent person to oversee and manage the trial pit activities. Mandate the use of appropriate personal protective equipment (PPE), including hard hats, gloves, high-visibility clothing, and sturdy footwear. Identify and locate underground utilities before starting the trial pit excavation. Use proper methods such as utility maps, ground-penetrating radar, or contacting utility owners. Develop a clear plan for trial pit excavation, including the intended depth and dimensions. Consider factors such as soil conditions, adjacent structures, and safety measures. Evaluate the stability of the trial pit walls and take necessary measures to prevent collapses. Avoid using any mechanical equipment and any sharp hand tools to prevent any untoward incident that may damage existing underground utilities. Apply manual excavation during trial pits works. Use proper sloping or shoring techniques based on soil conditions. Provide safe and easy access and egress points for workers within the trial pit. Install ladders, stairways, or ramps as needed for safe entry and exit. Erect protective barriers, such as fencing or barricades, around the trial pit to prevent unauthorized access. Monitor weather conditions and consider how they might affect soil stability. Suspend trial pit activities during adverse weather conditions, such as heavy rain. Establish and communicate emergency procedures, including evacuation routes, in case of unforeseen circumstances. Ensure that workers know the location of emergency equipment, such as rescue gear and first aid supplies. Conduct regular inspections of the trial pit site, including the stability of the excavation walls. Provide comprehensive training for workers involved in trial pit activities, emphasizing hazard recognition and the proper use of safety measures. Encourage open communication among workers to report unsafe conditions or concerns. Implement proper soil handling procedures, including stockpiling soil away from the excavation site to prevent collapse or slippage. Consider the environmental impact of trial pit activities, especially in ecologically sensitive areas. Implement measures to prevent soil erosion and minimize disturbance to the surrounding environment."],"revisedProbability":1,"revisedSeverity":3},{"id":8,"activity":"Excavation","hazards":["Collapse of excavation Cave-in Fall of men and materials Slip, trip and falls Damaging the underground utilities, spark, explosion, fire, overflow Personal injury/health defects, Property/equipment damage, Environmental impact"],"probability":4,"severity":3,"controls":["Provide comprehensive training for all workers involved in excavation, including the recognition of hazards and the proper use of protective systems. Designate a competent person to oversee and manage the excavation site. Mandate the use of appropriate personal protective equipment (PPE), including hard hats, gloves, high-visibility clothing, and sturdy footwear. Before excavation begins, identify and locate all underground utilities using proper methods such as utility maps, ground- penetrating radar, or contacting utility owners. Clearly mark the location of utilities to prevent accidental damage. Develop a detailed excavation plan that includes the layout of the site, depths of excavation, and the type of protective system to be used. Consider factors such as adjacent structures, traffic, and the proximity of utilities. Choose and implement the appropriate protective system based on the soil type and depth of excavation. Common protective systems include shoring, sloping, and trench boxes. Before excavation begins, identify and locate all underground utilities using proper methods such as utility maps, cable avoidance tool, or contacting utility owners. Provide safe and easily accessible entry and exit points for workers within the excavation. Install ladders, stairways, or ramps as necessary for safe access and egress. Regularly inspect the soil conditions within the excavation to identify any signs of instability. Address changes in soil conditions promptly and adjust protective measures accordingly. Erect protective barriers, such as fencing or rigid barricades, appropriate sign boards around the excavation site to prevent unauthorized access by workers or the public. Implement fall protection measures for workers near the edges of excavations. Establish and communicate emergency procedures, including evacuation routes, in case of cave-ins or other emergencies. Conduct regular inspections of the excavation site, protective systems, and equipment. Comply with ADOSH CoP 29.0 Excavation Work"],"revisedProbability":1,"revisedSeverity":3},{"id":9,"activity":"Dewatering works","hazards":["Entanglement of body part while using any mechanical equipment. Cut/hit by equipment Flooding Personal injury/health defects Property/equipment damage Environmental impact"],"probability":4,"severity":3,"controls":["Ensure that personnel involved in dewatering are trained and competent in the safe operation of dewatering equipment. Designate a competent person to oversee and manage the dewatering activities. Regularly inspect and maintain dewatering equipment to ensure it is in good working condition. Provide and enforce the use of appropriate personal protective equipment (PPE), including hard hats, gloves, high-visibility clothing, and steel-toed boots. Avoid loose clothing during operation. Ensure that all rotating parts are guarded and secured properly. Implement electrical safety measures when using electrically powered dewatering equipment. Establish safe access and egress points for workers and equipment involved in dewatering. Install guardrails, ladders, or ramps as necessary. If dewatering involves excavations or trenches, implement proper trench safety measures, such as shoring, sloping, or using trench boxes. Consider the environmental impact of dewatering, especially in ecologically sensitive areas. Implement erosion control measures to prevent soil erosion and sedimentation. Monitor water levels, groundwater flow, and surrounding structures during dewatering. Use monitoring devices to track changes and adjust dewatering efforts accordingly. Ensure that discharged water is properly managed to prevent erosion and potential environmental contamination. Comply with local regulations regarding the discharge of water. Control vehicular and pedestrian traffic in the dewatered area. Use barricades, signage, and flaggers to control traffic and prevent unauthorized access. Develop and communicate emergency procedures, including evacuation routes, in case of unforeseen circumstances or emergencies. Ensure that all workers are familiar with emergency protocols. Monitor weather conditions and adjust dewatering efforts accordingly. Suspend dewatering activities during adverse weather conditions if necessary. Establish clear communication channels between equipment operators, workers, and site supervisors. Provide comprehensive training to workers on the safe operation of dewatering equipment and adherence to safety procedures. Conduct regular toolbox talks to reinforce safety awareness. Keep thorough records of safety inspections, training sessions, dewatering parameters, and any incidents or near- misses during the dewatering works. Comply as per ADOSH COP-36.0."],"revisedProbability":1,"revisedSeverity":3},{"id":10,"activity":"Tower Crane Installation","hazards":["Collision, Man/Machine interface Pinch Points Falling of materials from Trailer"],"probability":4,"severity":3,"controls":["Ensure all operatives are trained for manual handling. Ensure safe place to work for crane components installation area (like: even ground level with adequate protection of surface) provided. Appointed lifting person shall ensure all lifting activities in compliance with as PER ADOSH-SF) CoP 34.0 - Safe Use of Lifting Equipment and Lifting Accessories. Ensure all lifting equipment and lifting accessory are inspected and color coded/ Tag Displayed appropriately. Ensure all personnel are properly trained in crane operations and Follow safe System of work. Adequate supervision by (NFT) tower crane specialist. Lifting Permit shall be Obtained prior to work. MSRA shall be communicate prior to work. Ensure all lifting equipment and lifting accessories are inspected and color coded/ Tag displayed appropriately. Crane shall be inspected by the operator and Lifting supervisor with the use of checklist in daily basis prior to commence the lifting activity. Periodic maintenance shall be carried out for the crane and record to be maintained. Crane lifting radius shall be barricaded and warning signages to be provided. Crane components assembling area shall be isolated by the provision of appropriate barricade and warning signages Adequate Communication (Radio) shall be established between rigger and operator. Ensure Signal communication only with authorized rigger and operator. Ensure Strict compliance of ADOSH-SF CoP 23.0 Working at height. Ensure suitable & sufficient fall protection prevention (Safety Harness, Lifeline, fall arrestor……) of a safe system of work shall be implemented. Personnel adhere with 100% tie-off in working at height. Ensure minimum of 2 taglines provided to control the load appropriately. Ensure Adequate competent supervision at all the time. Riggers and operators to be briefed on the correct slinging methods for the task by the appointed Certified lifting supervisor. Safe access and egress to be provided for the operation team. Ensure all lifting equipment and lifting accessories are approved by 3rd party company Accredited by ADM. Ensured inspection of Boom installed safe as per design/ Drawing. Ensure Strict Compliance with Aldar OHSMS Rev.8. Use appropriate personal protective equipment (Hard Hat, Hand Gloves, Safety Goggles and High Visibility) as per ADOSH-SF CoP 2.0 – Personal Protective Equipment."],"revisedProbability":1,"revisedSeverity":3},{"id":11,"activity":"Backfilling and levelling","hazards":["Vehicle/equipment Collision Collision of vehicles/equipment, Entanglement Personal injury/health defects, Property/equipment damage Environmental impact"],"probability":4,"severity":3,"controls":["Ensure that workers involved in backfilling are trained and competent in safe work practices. Designate a competent person to oversee and manage the backfilling activities. Mandate the use of appropriate personal protective equipment (PPE), including hard hats, gloves, high-visibility clothing, and steel-toed boots. Train workers on proper manual handling techniques to minimize the risk of musculoskeletal injuries during material handling and backfilling. Ensure that compaction equipment is operated by trained personnel. Clearly mark the area being compacted, and keep workers away from the equipment during operation. Implement proper trench safety measures, including shoring, sloping, or using trench boxes. Establish safe slope angles for backfilled areas to prevent slope failure. Monitor the stability of the backfilled slopes during and after the process. Restrict vehicular and pedestrian traffic in the backfilled area during the process. Use barricades, signage, and flaggers to control traffic and prevent unauthorized access. Provide edge protection, such as guardrails or barriers, around excavations to prevent workers from accidentally falling in. Monitor weather conditions, especially during adverse weather, and suspend backfilling activities if necessary to ensure worker safety. Establish clear communication channels between equipment operators, workers, and supervisors. Develop and communicate emergency procedures, including evacuation routes, in case of unforeseen circumstances or emergencies. Ensure that all workers are familiar with emergency protocols. Implement erosion control measures to prevent soil erosion and sedimentation during backfilling. Consider the environmental impact and take steps to minimize disruption to the surrounding area. Regularly inspect and maintain backfilling equipment to ensure it is in good working condition. Conduct regular toolbox talks to review safety procedures and address any specific hazards associated with the backfilling project. Provide ongoing training to workers on safe backfilling practices. Keep thorough records of safety inspections, training sessions, and any incidents or near-misses during the backfilling works. Comply with ADOSH CoP 29.0 Excavation Work"],"revisedProbability":1,"revisedSeverity":3},{"id":12,"activity":"Lifting operation","hazards":["Unsafe operations and tools could cause workplace injuries. Personal Injury Major and multiple injury, Property damage"],"probability":4,"severity":3,"controls":["Develop a detailed lifting plan that includes information about load weight, lifting points, rigging configuration, and environmental conditions. Communicate the lifting plan with all personnel involved in the operation. Ensure that only trained and competent personnel operate lifting equipment. Provide specialized training for operators, riggers, and signalers involved in the lifting operation. Regularly inspect and maintain lifting equipment to ensure it is in good working condition. Conduct pre-use checks before each lifting operation. Pre-task briefing and toolbox talk to be conducted with the workforce prior commencing lifting operations. Permit to work to be obtained prior starting activity and be in place during the duration of the lifting operation. Ensure that the lifting equipment used has the capacity to handle the intended load. Clearly mark load capacities and limitations on equipment. Use appropriate and properly maintained slings, chains, or other rigging equipment. Inspect rigging components for wear, damage, or defects before each use. Establish clear communication channels between the lifting equipment operator, riggers, and signalers. Use standardized hand signals or radios for communication during lifting operations. Establish exclusion zones around the lifting area to prevent unauthorized personnel from entering. Clearly mark and communicate the boundaries of these zones. Assess the stability of the ground where lifting equipment is positioned. Monitor weather conditions and suspend lifting operations during adverse weather, such as high winds or storms. Ensure that the load is properly secured and balanced before lifting. Use appropriate slings or attachments to prevent load shifting. Maintain detailed records of equipment inspections, lifting plans, and operator certifications. Document any incidents or near-misses and use them as learning opportunities. Provide ongoing training and refresher courses for personnel involved in lifting operations to keep their skills and knowledge up-to-date. Develop and communicate emergency procedures, including procedures for equipment malfunctions, dropped loads, or accidents. Ensure that all personnel are familiar with emergency evacuation routes. Comply as per ADOSH COP-34.0 Safe Use of Lifting Equipment and Lifting Accessories"],"revisedProbability":1,"revisedSeverity":3},{"id":13,"activity":"Wetmix Plant Operation","hazards":["Manual Handling Falling Objects Moving Parts Hot Surfaces Noise Hazards Dust Exposure Slips, Trips, and Falls Fire and Explosion Risks Environmental Impact Electrical Hazards"],"probability":4,"severity":3,"controls":["Provide thorough training for operators on the safe operation of the wetmix plant. Ensure that operators are familiar with all the plant components, control systems, and emergency procedures. Mandate the use of appropriate PPE, such as hard hats, safety glasses, hearing protection, gloves, and high-visibility clothing. Develop and communicate emergency procedures, including protocols for equipment malfunctions, fires, or other emergencies. Conduct regular emergency drills to ensure everyone is familiar with the procedures. Establish a routine inspection and maintenance schedule for all components of the wetmix plant. Conduct pre-start checks to ensure that all equipment is in proper working order. Clearly mark hazardous areas, emergency exits, and safety instructions with appropriate signage. Use warning signs to highlight potential dangers. Implement fall protection measures for personnel working at elevated locations, such as on top of silos or platforms. Provide guardrails, safety nets, or personal fall arrest systems as needed. Control vehicular and pedestrian traffic around the wetmix plant area. Use designated walkways and roadways, and install barriers or signage to guide traffic safely. Properly handle and store hazardous materials, such as bitumen or chemical additives, according to safety regulations. Train personnel on the safe handling and storage of these materials. Install fire extinguishers and firefighting equipment at strategic locations around the wetmix plant. Conduct regular fire drills and ensure that personnel know how to use firefighting equipment. Implement measures to control noise levels in and around the wetmix plant. Provide hearing protection for personnel working in noisy areas. Implement effective dust control measures to reduce airborne dust. Use dust suppression systems or water sprays as needed. Train personnel on proper material handling techniques to prevent injuries during loading and unloading operations. Use appropriate lifting equipment and follow safe lifting practices. Consider the environmental impact of wetmix plant operations. Implement measures to prevent soil erosion, manage water runoff, and minimize pollution. Ensure proper ventilation in enclosed areas to prevent the buildup of fumes or gases. Install exhaust systems as needed. Keep detailed records of equipment inspections, maintenance activities, safety training sessions, and emergency drills. Document any incidents, near-misses, or corrective actions taken."],"revisedProbability":1,"revisedSeverity":3},{"id":14,"activity":"Asphalt Works","hazards":["Exposure to Asphalt Fumes Burns and Skin Irritation Contact with Hot Equipment Manual Handling Injuries Noise Exposure Equipment Movement Hazards Exposure to Dust Slip, Trip, and Fall Hazards Heat Stress Environmental Impact"],"probability":4,"severity":4,"controls":["Mandate the use of appropriate PPE, including hard hats, safety glasses, high-visibility clothing, gloves, and steel-toed boots. Consider respiratory protection for workers exposed to asphalt fumes. Provide comprehensive training for all personnel involved in asphalt works, covering safe operating procedures, hazard recognition, and emergency response. Conduct regular refresher training sessions. Establish a routine inspection and maintenance schedule for all asphalt equipment, including pavers, rollers, and asphalt plants. Conduct pre-use checks before each shift. Implement effective traffic control measures to protect workers and manage vehicle movement in and around the work zone. Use signage, barricades, and flaggers to direct traffic. Train workers on proper material handling techniques to prevent injuries during loading, unloading, and transport of asphalt materials. Moving equipment should be controlled by trained flagman’s. Use appropriate lifting equipment and follow safe lifting practices. Establish procedures for the safe handling of hot mix asphalt to prevent burns or skin injuries. Provide insulated gloves and other protective gear for workers handling hot materials. Install fire extinguishers and firefighting equipment at strategic locations. Ensure workers are trained in the use of firefighting equipment and emergency evacuation procedures. Provide proper ventilation for areas where workers are exposed to asphalt fumes, especially around asphalt plants and paving operations. Use exhaust systems to remove fumes. Implement measures to prevent heat-related illnesses, especially during hot weather. Provide shaded rest areas, hydration stations, and encourage frequent breaks. Implement effective dust control measures to minimize airborne dust during asphalt mixing and paving. Use water sprays or other dust suppression systems. Ensure that asphalt equipment is equipped with proper machine guarding to prevent contact with moving parts. Train operators on the importance of machine safety. Establish clear communication channels between equipment operators, workers, and supervisors. Use radios or other communication devices to maintain contact during asphalt works. If asphalt works involve excavations or trenches, implement proper trench safety measures, such as shoring or sloping, to prevent collapses. Develop and communicate emergency procedures, including protocols for equipment malfunctions, spills, and injuries. Ensure that all workers are familiar with emergency evacuation routes. Consider the environmental impact of asphalt works, including proper disposal of waste materials. Implement measures to prevent spills and contamination. Keep detailed records of safety inspections, training sessions, equipment maintenance, and any incidents or near-misses during asphalt works."],"revisedProbability":1,"revisedSeverity":3},{"id":15,"activity":"Precast Activities","hazards":["Manual Handling and Ergonomic Hazards Fall Hazards Crushing and Pinching Hazards Machine and Equipment Hazards Electrical Hazards Traffic Hazards Noise Hazards Weather Conditions Environmental Impact Inadequate Personal Protective Equipment (PPE)"],"probability":4,"severity":4,"controls":["Provide thorough training for all personnel involved in precast activities, including manufacturing, handling, transportation, and installation. Ensure workers are familiar with equipment operation and emergency procedures. Mandate the use of appropriate PPE, including hard hats, safety glasses, gloves, high-visibility clothing, and steel-toed boots. Consider additional PPE based on specific job tasks. Regularly inspect and maintain precast manufacturing equipment to ensure it is in good working condition. Conduct pre-use checks before each shift. Train workers on proper material handling techniques to prevent injuries during the manufacturing, storage, and transportation of precast elements. Use appropriate lifting equipment and follow safe lifting practices. Implement fall protection measures for workers operating at elevated heights during the manufacturing or installation of precast elements. Provide guardrails, safety nets, or personal fall arrest systems as needed. Implement effective traffic control measures in manufacturing yards and construction sites where precast elements are transported and installed. Use designated walkways and roadways, and install barriers or signage to guide traffic safely. Ensure that manufacturing equipment is equipped with proper machine guarding to prevent contact with moving parts. Train operators on the importance of machine safety. Develop and communicate emergency procedures, including protocols for equipment malfunctions, falls, or other emergencies. Conduct regular emergency drills. Install fire extinguishers and firefighting equipment in precast manufacturing facilities and at construction sites. Conduct fire drills and ensure that workers know how to use firefighting equipment. Establish clear communication channels between equipment operators, workers, and supervisors. Monitor weather conditions and adjust precast activities accordingly. Suspend activities during adverse weather conditions, such as high winds or storms. Keep detailed records of safety inspections, training sessions, equipment maintenance, and any incidents or near-misses during precast activities. Document quality control procedures and inspections. Consider the environmental impact of precast activities, including proper disposal of waste materials and pollution prevention measures."],"revisedProbability":1,"revisedSeverity":3},{"id":16,"activity":"Working at Height","hazards":["Fall from Heights Falling Objects Unstable Surfaces: Equipment Failure: Weather Conditions: Lack of Guardrails or Barriers Unprotected Floor Openings Misuse of Fall Protection Equipment: Inadequate Training Overloading Platforms Unsecured Tools and Materials Insufficient Personal Protective Equipment (PPE)"],"probability":4,"severity":3,"controls":["Prioritize fall prevention measures over fall protection. Use guardrails, barriers, or safety nets to prevent falls wherever possible. Install guardrails and barriers at the edges of elevated platforms or working areas. Ensure that guardrails meet height and strength requirements. Use safety nets as a secondary measure to protect workers from falls. Nets should be installed close to the working surface and be properly secured. When guardrails and barriers are not feasible, implement personal fall protection systems. Use fall arrest systems, such as harnesses, lanyards, and anchor points. Install secure anchor points to which personal fall protection equipment can be attached. Ensure anchor points are capable of supporting the loads applied in the event of a fall. Provide workers with appropriate fall arrest equipment, including harnesses, lanyards, and self-retracting lifelines. Ensure equipment is regularly inspected and maintained. Train workers on the specific hazards of working at height, proper use of equipment, and emergency procedures. Ensure workers are aware of the importance of inspecting their equipment before use. Use proper access equipment, such as ladders, scaffolds, or elevated work platforms, when working at height. Ensure that access equipment is stable, in good condition, and used according to safety guidelines. Guard floor openings and edges to prevent accidental falls. Use covers, guardrails, or safety nets to secure openings. Secure tools and materials when working at height to prevent them from falling. Use tool lanyards, tethered tools, or tool bags to secure equipment. Monitor weather conditions, especially wind, rain, or adverse weather, and suspend work if conditions pose a safety risk. Develop and communicate an emergency rescue plan for workers working at height. Ensure that all workers are familiar with rescue procedures and equipment. Regularly inspect all equipment, including access equipment, fall protection systems, and guardrails. Replace or repair any damaged or faulty equipment promptly. Have competent supervisors oversee work at height activities. Monitor compliance with safety procedures and provide guidance to workers. Establish clear communication channels between workers, supervisors, and other personnel involved in the task. Use radios or other communication devices when necessary. Keep detailed records of risk assessments, safety training, equipment inspections, and any incidents or near-misses related to working at height."],"revisedProbability":1,"revisedSeverity":3},{"id":17,"activity":"Traffic Management for road diversion","hazards":["Vehicle-Related Hazards Pedestrian Risks Road Surface and Environmental Hazards Worksite Hazards Signage and Barrier Hazards Traffic Congestion and Delays Electrical and Utility Hazards Weather-Related Hazards"],"probability":4,"severity":4,"controls":["Permit to work to be obtained from concerned authorities. Install advance warning signs well ahead of the detour location to alert drivers about upcoming changes in the road. Use clear and standardized signage to provide information about the detour, including direction and distance. Clearly mark detour routes with appropriate signs, indicating the alternate path that drivers should follow. Use temporary signs and pavement markings to guide drivers along the detour route. Use traffic cones and barriers to clearly delineate the detour route and prevent drivers from straying into the construction zone. Ensure that barriers are highly visible and adequately spaced to guide traffic safely. Install temporary traffic signals at intersections along the detour route to manage the flow of traffic and prevent congestion. Coordinate signal timings to optimize the efficiency of the detour. Deploy trained flaggers or traffic control personnel at critical points to direct traffic, especially at intersections and points where the detour route may be confusing. Ensure that flaggers are equipped with high-visibility clothing and proper signaling tools. Coordinate with emergency services to ensure that detour routes are accessible and safe for emergency vehicles. Develop contingency plans for handling emergencies within the detour area. Conduct regular inspections of the detour route to identify and address any issues promptly. Ensure that temporary signage, road markings, and barriers remain in good condition. Monitor traffic flow along the detour route and make adjustments as needed. Implement changes to the detour plan based on real-time data and feedback from traffic monitoring systems."],"revisedProbability":1,"revisedSeverity":3},{"id":18,"activity":"Electricity","hazards":["Shock Electrocution and Physical injury on body. Personal Injury Major and multiple injury Property damage"],"probability":4,"severity":4,"controls":["Ensure that workers are adequately trained in electrical safety procedures. Provide specific training for tasks involving electrical work, including proper use of equipment and tools. Designate qualified and authorized personnel to perform electrical work. Ensure that workers have the necessary skills, knowledge, and experience for the specific tasks they are assigned. Provide and mandate the use of appropriate PPE, such as insulated gloves, safety glasses, flame-resistant clothing, and face shields. Ensure that PPE is properly maintained and regularly inspected. Implement and follow lock-out/tag-out procedures to de- energize electrical systems before performing maintenance or repair work. Clearly label and secure electrical disconnects and control points. Conduct a thorough electrical hazard analysis before starting any work on electrical systems. Identify potential electrical hazards and take appropriate measures to control or eliminate them. Assess the risk of arc flashes and provide appropriate protective measures, including arc-resistant clothing and barriers. Display arc flash warning labels on electrical equipment. Regularly inspect and maintain all electrical equipment to ensure it is in good working condition. Repair or replace damaged equipment promptly. Implement effective grounding systems to prevent the build- up of voltage and reduce the risk of electrical shock. Ensure that equipment and tools are properly grounded. Maintain safe distances from energized equipment and conductors to prevent accidental contact. Use appropriate barriers and safety signs to demarcate restricted areas. Establish a permit-to-work system for electrical work, especially for high-risk tasks. Ensure that proper authorization is obtained before starting work on electrical systems. Develop and communicate a comprehensive emergency response plan for electrical incidents. Train workers on emergency procedures, including first aid and the use of firefighting equipment. Regularly review and update electrical safety procedures based on changes in equipment, systems, or work processes. Encourage a culture of continuous improvement and awareness of electrical safety. Ensure that all electrical work complies with relevant national and international safety standards and regulations."],"revisedProbability":1,"revisedSeverity":3},{"id":19,"activity":"Working with heavy machineries","hazards":["Vehicle/equipment Collision Hit by vehicles/equipment Entanglement Environmental pollution Personal injury/health defects Property/equipment damage Environmental impact"],"probability":4,"severity":3,"controls":["Operate only certified equipment’s and lifting tools. Operators must have third party certificate. Preventive maintenance & inspection to be done for all equipment periodically. Ensure that ground condition is suitable for vehicle maneuvering. Do not exceed Safe Working Load. Deploy banksman adequate for heavy vehicles. Inspect all equipment’s. Enhance that works is safe to free from damage of O/H and U/G. The equipment’s should be lowered to ground whenever the backhoe is operated in poor soils conditions which could cause stabilizers to sink. Workmen are informed to wear reflective jacket and another required PPE. Conduct toolbox talks for safe operation of machineries. Comply as per ADOSH COP-36.0 Plant & Equipment."],"revisedProbability":1,"revisedSeverity":3},{"id":20,"activity":"Manual Excavation for relocating utility services","hazards":["Strike the underground utilities that may cause spark, explosion or fire Personal injury/health defects Property/equipment damage Environmental impact"],"probability":4,"severity":3,"controls":["Use hand shovel for excavation. Barricade the excavated area. Ensure Safe access and egress. Do not use existing utility services as platform or handhold. Secure live cables to avoid displacement. Cage or casings to be provided for existing utilities to prevent damage. While manual excavation, maintain safe distance between two workmen. Train workforce about safe work methods. The underground services shall not be forced /shifted by equipment’s. Make sure that competent supervision in place. Use designate devises to find out utilities. No workmen are allowed in case of any emergency. Inform concern authority immediately. Follow safe methods to prevent damage even utilities are not marked in as built drawings. Make shift work method to be followed when working under overhead lines. Comply as per ADOSH COP-29.0 Excavation Works"],"revisedProbability":1,"revisedSeverity":3},{"id":21,"activity":"Working nearby excavated area","hazards":["Collapse of excavation, Fall of men and materials Slip, trip and falls Personal injury/health defects Property/equipment damage Environmental impact"],"probability":4,"severity":3,"controls":["Provide hard barricading along excavated area. Provide warning light during night. Display necessary sign boards. Provide stop blocks where ever required. Ensure access and egress is safe to be with hand rail to reach all levels and maintained at all times. Prevent vehicle movements within 1.5m from excavated area. Safe access and egress must be provided with hand hold and edge limitation. Comply as per ADOSH COP-29.0 Excavation Works"],"revisedProbability":1,"revisedSeverity":3},{"id":22,"activity":"Working nearby utilities","hazards":["Collapse of excavation Fall of men and materials Slip, trip and falls, Damaging the underground utilities, spark, explosion, fire Personal injury/health defects, Property/equipment damage, Environmental impact"],"probability":4,"severity":3,"controls":["Obtain the permit/NOC from the service authorities. Permit to Work is to be adopted before execute work. Comply all relevant authorities code of practice for safe operations. Obtain utility drawings of the areas part of the permit to excavate system. Use pipe and cable locaters / detectors, every time to verify no cable. Train workforce to work nearby utility services. Concern engineer must direct workforce to follow SSOW. Use appropriate supporting system to withstand utilities while working across them. Comply as per ADOSH COP-29.0 Excavation Works"],"revisedProbability":1,"revisedSeverity":3},{"id":23,"activity":"Loading and unloading of materials","hazards":["Unsafe and unauthorized operation can cause hauling of work Property damage Personal injury Personal injury/health defects Property/equipment damage Environmental impact"],"probability":4,"severity":3,"controls":["Operate equipment’s and vehicles in stable condition. Engage competent operators. Load materials are evenly distributed. Workmen shall not be allowed while loading and unloading the materials more than 30kg. Use Stop blocks to avoid accidental tipping. Loading vehicles are parked nearby excavation in compliance with safe limits. Use appropriate PPE. Conduct TBT on safe handling procedures. Comply as per ADOSH CoP-44.0 Traffic Management and Logistics"],"revisedProbability":1,"revisedSeverity":3},{"id":24,"activity":"Preparation of subgrade and compaction, Laying geotextile sheeting","hazards":["Collision and striking by vehicles Equipment movements, Entanglement poor work posture Personal injury/health defects Property/equipment damage Environmental impact"],"probability":4,"severity":3,"controls":["Unauthorized trespassing is forbidden. Electrical cables are not trailed on soil. Implement a clear and specific traffic route. Vehicle flow is monitored and ensure competent supervision in place. Dumped/excavated soil shall not be kept nearby excavated area. Ensure that the area is free from any tripping hazard. Maintain safe distance from machineries to avoid injury. Display sign boards and make suitable arrangements for cautioning employees. All works to be carried out under competent supervision. Comply as per ADOSH CoP-44.0 Traffic Management and Logistics"],"revisedProbability":1,"revisedSeverity":3},{"id":25,"activity":"Operating heavy power or pneumatic equipped tools","hazards":["Entanglement of body part during operation Cut/hit by equipment, environmental pollution Personal injury/health defects Property/equipment damage Environmental impact"],"probability":4,"severity":3,"controls":["Machineries must have legal certificates. Deploy competent operators. Practice safe transportation of machineries. Machineries shall not be overloaded. Ensure guards are in place. No plant or equipment should be used if it is not in a safe working condition. Periodical maintenance must be in place. The plant and equipment’s should be kept tidy and free from tools. Maintain safe clearance distances between workmen and machineries. Use whip splash arrestors. Physical check to be done on hydraulic hoses for chafing and leakage, brakes, chains for lubrication and for foreign material caught in links. Provide required PPE to workforce. Comply as per ADOSH COP-35.0 Portable Power Tools"],"revisedProbability":1,"revisedSeverity":3},{"id":26,"activity":"Manual handling","hazards":["Entanglement of body part during operation, Cut/hit by equipment environmental pollution Personal injury/health defects Property/equipment damage Environmental impact"],"probability":4,"severity":3,"controls":["Follow safe manual lifting techniques. Assess the load prior to lift. Use mechanical equipment’s to lift the load more than 50 kg. Ensure that workers are trained regarding manual handling. Provide cushioning to the edges as far as possible. Ensure suitable hand protection and other personal protective equipment (Safety shoe/coverall/hard hat). Display appropriate warning sign. Comply as per ADOSH CoP 14.0 Manual handling and Ergonomics"],"revisedProbability":1,"revisedSeverity":3},{"id":27,"activity":"Blinding and Curb laying","hazards":["Slips, trips, nail pinching Ergonomics Personal injury/health defects Property/equipment damage Environmental impact"],"probability":4,"severity":3,"controls":["Mechanical tools are used to handle curbs. Workmen are trained on safe manual handling procedures. Protruding steel rods are capped. Maintain good housekeeping. Use appropriate tools for cutting of curbs. Make ensure that electricity is safe. Trailing of cables is routed safely. Wear necessary PPE and conduct TBT on SSOW. Comply as per ADOSH COP-14.0"],"revisedProbability":1,"revisedSeverity":3},{"id":28,"activity":"Working near traffic","hazards":["Unsafe and unauthorized operation can cause haunting of work Property damage and personal injury Environmental impact"],"probability":4,"severity":3,"controls":["Provide necessary sign boards, flashing light and reflective stickers while surveying nearby traffic area. All involved in the activity must wear high visibility vest or jackets. All involved in the activity to be aware of their own and their co-worker’s environment and exercise due care and attention. Crossing or horse play is strictly prohibited when vehicle movement is in progress. Safety zone delineated by cones and lamps are provided to protect operatives from the traffic and to protect traffic from road works. Display necessary sign boards. Comply as per ADOSH COP-44.0"],"revisedProbability":1,"revisedSeverity":3},{"id":29,"activity":"Application of the prime coat and tack coat.","hazards":["Health hazards Fire hazard & environmental impact as spillage. Major injury or health effect. Soil Contamination. Property damage"],"probability":4,"severity":3,"controls":["Toolbox talk to be conducted before work starts. Provision of suitable fire extinguisher in reach. Any bitumen emulsion spillage should be combated immediately and the polluted soil must be collected and disposed according to) regulations Strictly no smoking at or close working area. Usage of proper PPE e.g. mask / respiratory protection, anti- heat gloves & apron, safety boot, goggles. Comply as per ADOSH COP-44.0"],"revisedProbability":1,"revisedSeverity":3},{"id":30,"activity":"Laying AC base and wearing courses","hazards":["Falling objects / materials during unloading. Tipper might turn-side which may cause injury and damage Major injury or health effect., Property damage"],"probability":4,"severity":3,"controls":["Tippers / trucks must not be fully loaded with materials. Toolbox talk before work commences. Proper distribution of the loaded asphalt in the tipper box. Adequate maintenance of the tippers & trucks (hydraulic system). Qualified drivers with heavy UAE driving license should only be allowed to drive. Usage of Personal Protective Equipment (PPE) such as helmet, safety goggles, & safety shoes. Comply as per ADOSH COP-44.0"],"revisedProbability":1,"revisedSeverity":3},{"id":31,"activity":"Rolling & compaction works","hazards":["Health hazards as release of noise and vibration caused by vibration steel- roller, & other related equipment. Minor injury or health effects, hearing problems, headaches. Allergies and first aid injuries. Property Damage"],"probability":4,"severity":3,"controls":["Ensure that operators are properly trained and certified to operate rolling and compaction equipment. Provide regular refresher training on safety procedures and equipment operation. Mandate the use of appropriate PPE, including high-visibility clothing, hard hats, steel-toed boots, gloves, and hearing protection. Consider respiratory protection for dusty or asphalt-related works. Conduct pre-operation checks and inspections of rolling and compaction equipment. Ensure that equipment is in good working condition and address any defects before use. Implement effective traffic control measures in work zones to prevent collisions between construction equipment and other vehicles or pedestrians. Use signage, barricades, and flaggers to guide traffic safely. Establish clear communication channels between equipment operators, spotters, and other personnel. Install audible warning systems, such as backup alarms, on rolling and compaction equipment to alert workers and others in the vicinity. Ensure that warning signals are distinct and easily recognizable. Enhance visibility on the worksite by using high-visibility clothing, proper lighting, and reflective markings on equipment. Minimize blind spots through the use of convex mirrors. Establish and enforce safe work practices for rolling and compaction activities. Define clear work zones and boundaries to prevent unauthorized personnel from entering hazardous areas. Ensure that the ground is stable and suitable for the operation of rolling and compaction equipment. Avoid working on slopes that exceed safe limits. Develop and communicate emergency procedures, including protocols for equipment malfunctions, accidents, and evacuation. Ensure that all workers are familiar with emergency response plans. Monitor weather conditions and suspend rolling and compaction works during adverse weather, such as heavy rain or lightning. Consider the impact of weather on soil or asphalt compaction. If rolling and compaction works involve excavations or trenches, implement proper trench safety measures, such as shoring or sloping, to prevent collapses. Conduct regular hazard assessments to identify potential risks associated with specific rolling and compaction tasks. Implement control measures to mitigate identified hazards. Ensure that equipment operators have clear visibility of the worksite and are aware of the locations of other workers and obstacles. Use spotters if necessary. Establish exclusion zones around rolling and compaction equipment to keep unauthorized personnel at a safe distance. Clearly mark and communicate the boundaries of exclusion zones. Maintain detailed records of equipment inspections, safety training, and any incidents or near-misses during rolling and compaction works. Consider the environmental impact of rolling and compaction activities, especially in terms of soil compaction or potential chemical exposure. Implement measures to prevent soil erosion or contamination."],"revisedProbability":1,"revisedSeverity":3},{"id":32,"activity":"Underground Services","hazards":["Property damage Major effect, loss of resource"],"probability":4,"severity":3,"controls":["Ensure safe access is provided for personnel. No excavation is allowed to proceed without a Permit to Excavate. Cable Avoidance Tools to be use for detection of underground utilities. Access ladders are to be used and secured to enter and exit the excavation. Barricades and Handrails are to be in-place if excavation depth exceeds 1.5m meters. Comply as per ADOSH COP-39.0"],"revisedProbability":1,"revisedSeverity":3},{"id":33,"activity":"Movement of vehicles and equipment.","hazards":["Collision between moving vehicles / equipment and objects or with workers. Personal injury/health defects Property/equipment damage, Environmental impact"],"probability":4,"severity":3,"controls":["Implement a clear and specific traffic route including (clear routes of ingress and exit, using guarding, barriers, cones, traffic signage and speed control). Toolbox talk before work commences. Maintaining proper vehicles conditions and maintenance, (seat belt, reversing horn, beacons, indicators, head lights, wipers). Provision of signal-man (banksman) where applicable. Comply as per ADOSH COP-44.0"],"revisedProbability":1,"revisedSeverity":3},{"id":34,"activity":"Working on site (outdoor)","hazards":["Slips, trips & falls (in wet ground). Environmental contamination and waste accumulation. Back injury, Personal injury"],"probability":4,"severity":3,"controls":["Tool box talk before work commences. Barricading the wet area, holes and pits. Collection of waste and littering in designated bins and containers. Tool box talk will include the waste management & housekeeping. Provision of suitable PPE (anti-slippery safety shoes). Comply as per ADOSH COP-11.0"],"revisedProbability":1,"revisedSeverity":3},{"id":35,"activity":"Working under the sun & high temperature","hazards":["Health hazards (sun stroke, dehydration and body fatigue). Equipment / Vehicles accidents. Human injury and property damage. Health hazard."],"probability":4,"severity":3,"controls":["Provision of cool water & mineral liquids. Tool box talk before work commences will be conducted. Work rotation to be implemented to prevent workers being exposed to heat for long time. Appropriate rest area to be provided in worksite. Comply as per ADOSH COP-11.0"],"revisedProbability":1,"revisedSeverity":3},{"id":36,"activity":"Steel Reinforcement Works","hazards":["Piercing, Back pain, Stabbing, Flying objects, Vibration Major injury, Personal injury/ health & Material damage."],"probability":4,"severity":3,"controls":["Steel rod bundles must be stacked not more than 1.5m at site premises. Trained person is used steel cutting, bending operations. Steel rod cutting machines are maintained well. Workmen are trained to handle sharp objects with utmost care. Use of mechanical aid for lifting steel rods. Appropriate PPE must be provided to work force like Hand gloves, safety shoe and protective clothing ...etc. Proper technique to be practiced if successive manual lifting in place. Protruding steel rods are covered by rebar caps. Display necessary sign boards. Comply as per ADOSH COP-8.0"],"revisedProbability":1,"revisedSeverity":3},{"id":37,"activity":"Shuttering and DE shuttering","hazards":["Flying objects, Hand injury Cut injury Fatality Property damage"],"probability":4,"severity":3,"controls":["Deploy competent person to do safe form work and Use sound materials and tied. Provide safe access and egress. If any fall hazards pose person must be instructed to hook the safety harness while working at the edges. Ensure condition of the PPEs (Shoes, helmet) is proper before start the job. Plywood and other materials should be unloaded on the safe accessible place. Train all the concern person about the hazards related to formwork. Ensure proper edge protection to be installed. Comply as per ADOSH COP-8.0"],"revisedProbability":1,"revisedSeverity":3},{"id":38,"activity":"Concreting","hazards":["Vehicle collision, striking by vehicles, Falls of materials Major injury, Personal Injury/ health & Material damage."],"probability":4,"severity":3,"controls":["Concrete mixer and pumps should be parked away from the edge of the excavation. Appropriate PPE to be use by the workforce. Concrete bucket must have valid certificate and operator to be trained. Appropriate lifting techniques are used. Taglines are used to control bucket movements. Provide necessary PPE and Display sign boards. Concrete bucket to be cleaned after concreting. Workmen are informed about pinching hazards. Comply as per ADOSH COP-1.0"],"revisedProbability":1,"revisedSeverity":3},{"id":39,"activity":"Chemical handling","hazards":["Chemical splashes, Acute and chronic effect Eye injury Inhalation Illness Property damage"],"probability":4,"severity":3,"controls":["Provide and ensure the use of appropriate PPE such as gloves, safety goggles, lab coats, and respiratory protection based on the nature of the chemicals being handled. Train personnel on the proper handling, storage, and disposal of chemicals. Ensure that employees are aware of the hazards associated with specific chemicals and understand emergency procedures. Store and handle chemicals according to their compatibility to prevent reactions and the release of hazardous substances. Ensure adequate ventilation in areas where chemicals are handled to minimize exposure to harmful fumes or vapors. Clearly label all containers with the contents, hazards, and proper handling instructions. Maintain accurate documentation of chemicals, including Safety Data Sheets (SDS) and inventory records. Establish and communicate emergency response procedures, including evacuation plans, first aid measures, and contact information for emergency services. Store chemicals in designated areas according to their compatibility and in appropriate containers. Use secondary containment systems to prevent spills and leaks. Follow established standard operating procedures (SOPs) for the handling and use of chemicals. Use proper equipment and tools for handling chemicals, and ensure that they are in good working condition. Conduct regular inspections of chemical storage areas, equipment, and handling procedures. Perform audits to assess compliance with safety protocols and identify areas for improvement. Implement proper waste disposal procedures for chemicals, following local regulations and guidelines. Establish clear communication channels among employees involved in chemical handling. Encourage reporting of any spills, leaks, or unsafe conditions. Provide first aid training to personnel handling chemicals. Implement medical surveillance programs to monitor the health of employees exposed to hazardous substances. Develop and implement a chemical hygiene plan that outlines procedures for safe chemical handling and laboratory activities. Comply as per ADOSH CoP 1.0 Hazardous Materials"],"revisedProbability":1,"revisedSeverity":3},{"id":40,"activity":"Water proofing","hazards":["Fire, Explosion Personal Injury, Major and multiple injury, Property damage"],"probability":4,"severity":3,"controls":["Display No smoking / No naked lights signage and store the chemicals in separate & well-ventilated and dry place. Use adequate PPE and provide Fire extinguisher. MSDS contents must be informed to users and displayed in the storage area. Obtain Hot work permit prior to starts the work. Use suitable Flash back arrestor and ensure hose clamping is in good condition. Keep cylinders in vertical position and do not roll for shifting. Check Gas leakage by using the soap solutions. Do not keep torch ideal with the flame on. Comply as per ADOSH CoP 1.0"],"revisedProbability":1,"revisedSeverity":3},{"id":41,"activity":"Installation of structures","hazards":["Fall of materials, Collapse of structures, Failure of lifting devises Personal Injury, Major and multiple injury Property damage"],"probability":4,"severity":3,"controls":["Lifting plan to be developed and implemented to ensure that work under safe methods. Ensure that lifting plan is communicated with the workforce. Use approved third party certified tools & tackles. Inspect lifting accessories prior to use. Ensure safe working load not exceed the limit. Engage competent person to place and fix the tackles. Provide adequate cushioning in between to protect load and sling if required. Maintain sling angle not more than 90 degrees in any case. (Angle between sling legs). Provide tag line under load. Deploy signal men. Comply PPE requirements. Cordon off the work area. Works shall be done under competent supervision. No person under load while lowering."],"revisedProbability":1,"revisedSeverity":3},{"id":42,"activity":"Installation of pipes and transporting granular materials","hazards":["Unsafe operations and tools could cause workplace injuries. Personal Injury, Major and multiple injury Property damage"],"probability":4,"severity":3,"controls":["The crane or any equipment’s used for lifting should be certified for use. Deploy Competent person to operate. Operator must have license and competent certificate. Use certified tools & tackles, Inspect the tackles prior to use. Maintain safe height limit working near overhead Ensure not exceeding SWL. Engage competent person for signaling and to place and fix the tackles. Provide tag line under load. Comply PPE requirements. Cordon off the work area. Works shall be done under competent supervision. No person under load while lowering. Lifting plan shall be generated and practiced. Comply as per ADOSH COP-34.0."],"revisedProbability":1,"revisedSeverity":3},{"id":43,"activity":"Drilling nearby utilities","hazards":["Utilities damage, blow out can be caused if excavation has no planning and safe control measures Personal Injury, Major and Multiple Injury Property damage"],"probability":4,"severity":3,"controls":["Before any digging takes places, a check must be made with all public and private utilities and a site clearance/NOC received from concerned. Utilities are marked on drawing and frequently referred by site execution team. Existing utilities indicator shall not be damaged or removed. Cable detector to identify the buried cables shall be used. Safe method of execution must be done prior to start. Mechanical excavators and Power tools should not be used within 0.5 m of a service. Trial/Pilot holes to be dug where necessary. Hands tools will be inspected daily by their users. Only deploy experienced personnel. Tool box meetings to be held to highlight hazards of UG live services. Barricade effectively. Provide flashing lights at night Minimum personnel to be involved in operation. Display sign boards to give clear indication of danger levels. Train workforce and staff about emergency response. Comply as per ADOSH COP-29.0."],"revisedProbability":1,"revisedSeverity":3},{"id":44,"activity":"Machine Rotating parts guarding","hazards":["Accidental contact, Absence of guard, Unauthorized operation Fatality, amputation, injury, crushing"],"probability":4,"severity":3,"controls":["Ensure proper guarding system in place for the rotating parts. If in built guarding is not available, then it should be guarded off by a fence to avoid unauthorized entry. Do not contact rotating parts, when machine in operation. Ensure the power is switched off when machine is not in use. Tag system must be followed during maintenance of the equipment. Training should be given to the personnel operating the equipment’s. Comply as per ADOSH COP-47.0"],"revisedProbability":1,"revisedSeverity":3},{"id":45,"activity":"Poor Illumination","hazards":["Inadequate illumination Routing of electrical cables, Substandard materials Injury to person Eye Stress Reduction in product quality"],"probability":4,"severity":3,"controls":["Maintain the Illumination min. 100 Lux. For general working. Glair should be avoided by suitable means or maintaining the reflector angle to a required angle. The electrical cables are routed safely to free from damage. All electrical works are done by competent person. ELCB provision must be required. Use necessary PPE and display sign boards. Comply as per ADOSH COP-15.0"],"revisedProbability":1,"revisedSeverity":3},{"id":46,"activity":"Emission of Noise","hazards":["Machinery operation Deafness"],"probability":4,"severity":3,"controls":["Perform regular noise assessments to identify areas with high noise levels. Use sound level meters to measure and monitor noise levels in different work areas. Implement engineering controls to reduce noise at the source, such as using quieter equipment or machinery. Enclose noisy equipment or use barriers to contain noise. Implement administrative controls to limit exposure time to high noise levels. Rotate workers to minimize their time in noisy areas. Provide appropriate hearing protection devices (HPDs) such as earplugs or earmuffs. Ensure that workers are trained on the proper use, fitting, and maintenance of hearing protection. Consider noise reduction measures during the design and selection of equipment and machinery. Choose quieter tools and machinery whenever possible. Isolate noisy equipment or processes from work areas or use barriers to contain noise. Design workspaces to minimize the transmission of noise. Ensure that machinery and equipment are well-maintained to minimize noise emissions. Address any mechanical issues promptly to prevent increased noise levels. Provide training to workers on the risks of noise exposure and the importance of using hearing protection. Educate employees about the long-term consequences of excessive noise on hearing health. Clearly mark areas with high noise levels with signage to alert workers and visitors. Use warning signs to indicate the need for hearing protection. Limit the time workers spend in high-noise areas. Schedule breaks in quieter areas to allow for recovery from noise exposure. Implement regular health surveillance programs to monitor workers' hearing health. Encourage workers to report any signs of hearing issues promptly. Install physical barriers or acoustic panels to absorb or block noise. Arrange workstations to create natural barriers between noise sources and workers. Designate quiet areas where workers can take breaks away from noisy environments. Provide a space for meetings or communication that is away from high- noise areas. Regularly monitor noise levels to ensure that they remain within acceptable limits. Enforce the use of hearing protection and other safety measures consistently. Establish and communicate clear occupational health and safety policies regarding noise exposure. Include noise control measures in the overall safety program. Conduct regular audits of noise control measures and revise them as needed. Stay informed about technological advancements in noise reduction and control. Ensure compliance with relevant occupational health and safety regulations regarding noise exposure. Keep records of noise assessments, control measures, and employee training."],"revisedProbability":1,"revisedSeverity":3},{"id":47,"activity":"Cable laying","hazards":["Back Pain, Sprain, Collapse of cable drum, Entanglement, Major injury, Personal injury& Material damage"],"probability":4,"severity":3,"controls":["Unloading place should be levelled, barricaded. All the lifting tools and tackles must be certified by third party. Cable drum should be unloaded with base frame to prevent accidental movement. All workmen who are deployed for cable pulling works are trained about handling of cables. Kinetic method of manual material handling should be followed. Cable roller is handled with utmost care under competent supervision. Comply as per ADOSH COP-15.0"],"revisedProbability":1,"revisedSeverity":3},{"id":48,"activity":"Jointing, termination and connection.","hazards":["Cut injury, flying particles Handling of cable jointing devices Major and multiple injury Occupational illness"],"probability":4,"severity":3,"controls":["Proper laying of the cable. Any undesired items and objects must be cleared from the working area. Provision of good safety shoes and helmet. Deployment of competent personal for cable join work, use mechanical tools if manual system is not suitable. Suitable measures are followed to prevent entanglement. Comply necessary PPE and conduct TBT by weekly on safe instructions. Comply as per ADOSH COP-15.0"],"revisedProbability":1,"revisedSeverity":3},{"id":49,"activity":"Grinding","hazards":["Foreign particles, Breaking of disc, Electricity Personal Injury, Major and minor injury"],"probability":4,"severity":3,"controls":["Ensure wheel RPM is always more than the spindle RPM. Select the right wheel for the right job. Visually inspect the spindle and wheel prior to use. The guard must be securely attached to the body of machine. Impart training on use of abrasive wheel operation. Display authorized persons list at the workplace/stores to avoid unauthorized operation. Avoid loose clothing during operation. Maintain the safe distance from the rotating part. Tool rests must be secured and maintain at least 3mm gap between tool rest and the wheel. Proper housekeeping must be maintained near the working area. Ensure adequate & proper illumination. Display of warning sign boards and notices. PPE (face shield, goggles, hand gloves, nose mask) must be worn as applicable. Comply as per ADOSH COP-35.0"],"revisedProbability":1,"revisedSeverity":3},{"id":50,"activity":"Painting works","hazards":["Chemical substances Occupational illness"],"probability":4,"severity":3,"controls":["The spray machine shall meet safety standards. Deploy authorized person to perform job. The electrical cables should free from damage. Adequate guards must be in place. Safe mixture of paints is to be done. Warning signs to be positioned adjacent to work area Follow the safe working procedures that are mentioned in the MSDS while working. Monitor the wind speed during spray painting. Minimize the quantity of chemicals at the work place by bringing. Whatever necessary for the daily work. Containment - the work area with warning tapes and warning signs. Provide watchmen to avoid unauthorized entry in the work area. Isolate the unwanted employees and materials. Physically competent and trained operatives for coating works. Toolbox Talks in regards to precautions (Risk Assessment). Use necessary PPE. Train the workmen. No mechanical cutting on painting tins. Store paints under shed area which has necessary firefighting materials. Communicate the MSDS of paints. Use appropriate personal protective equipment (Hard Hat, Safety shoe Hand Gloves, Safety Goggles and High Visibility) as per ADOSH-SF CoP 2.0 – Personal Protective Equipment. Ensure all paint work is carried out in accordance with ADOSH CoP 1.0 – Hazardous Materials"],"revisedProbability":1,"revisedSeverity":3},{"id":51,"activity":"Welding operation","hazards":["Welding and cutting, Fire Electrocution and illness problems Personal Injury, Major and minor injury Occupational illness"],"probability":4,"severity":3,"controls":["Use suitable machine for welding with safe amperage. Inspect welding machine about physical damage, electrical cable damage, guarding etc. Deploy competent welder to operate and carry out welding. Deploy competent supervision. The welding set will be inspected by a competent electrician prior to the installation. Use standard materials for electrical connection. Earthing must be in place for machine as well as connection. The earth lead will be connected securely to a clean surface, if using a welding table, the earth will be attached directly to the material being welded to prevent un-necessary arching. All cables will be arranged in a way they cannot be damaged. Display warning signs. Comply as per ADOSH COP-28.0"],"revisedProbability":1,"revisedSeverity":3},{"id":52,"activity":"Access and egress","hazards":["Fall of ladder, falls, slips, trips Major and minor injuries,"],"probability":4,"severity":3,"controls":["Maintain ladders free of oil, grease and other Slipping hazards. Secure ladder. Do not load ladders beyond their maximum intended load nor beyond their manufacturer’s rated capacity. Do not move, shift or extend ladders while in use. Do not carry objects or loads that could cause loss of balance and falling. Comply as per ADOSH COP- 37.0"],"revisedProbability":1,"revisedSeverity":3},{"id":53,"activity":"Power Tools","hazards":["Electricity and Physical injury on body Personal Injury, Major and multiple injury Property damage"],"probability":4,"severity":3,"controls":["Use power tools after inspection. Double insulated wires to be used for cables, Use industrial sockets. Trailing cable in dry condition and not to get damage by movement of equipment’s, Place fire extinguishers. Give regular training to the operators. Use good quality and properly rated and double insulated power cables without any cut, damages. Dragging of cable is forbidden and unplugs it when not in use. Do not operate power tools standing on a wet surface. Provide 30mA ELCB tripping rated in all temporary electrical sign boards. Provide adequate PPE. Comply as per ADOSH COP-35.0"],"revisedProbability":1,"revisedSeverity":3},{"id":54,"activity":"Handling and shifting of pumps","hazards":["Lifting of pumps, Working near excavation. Major and minor injuries, Severe property damage"],"probability":4,"severity":3,"controls":["Operate the certified equipment’s by competent operator. Lifting tools are free from damage. Observe Safe lifting practices as per lifting plan. Keep work area clear. Provide necessary PPE. Train the employees. Lifting area is forbidden for unauthorized entry. Place pump 1m away for manhole. Inspect pump about accidental movements regularly. Secure pump. No workmen allowed if any potential hazards exist. Comply as per ADOSH COP-14.0 & 44.0"],"revisedProbability":1,"revisedSeverity":3},{"id":55,"activity":"Handling of fuel","hazards":["Chemical exposure, Major and minor injuries,"],"probability":4,"severity":3,"controls":["Store the fuel in safe storage area. Keep the fuel in appropriate container. Use standard labelling. Train workforce about MSDS. Implement No Smoking policy. Display signage. Provide PPE. Fire extinguishers and spill kit availability. Remove combustible/flammable materials nearby storage area. Deploy competent person for handling. Use funnel if tank is intended. Comply as per ADOSH COP-7.0"],"revisedProbability":1,"revisedSeverity":3},{"id":56,"activity":"Working in Confined Space","hazards":["Lack of ventilation Toxic and Explosive gases Personal Injury Major and multiple injury Property damage"],"probability":4,"severity":3,"controls":["Evaluate the likelihood and severity of each identified hazard. Use a permit-to-work system to manage and control entry into confined spaces. Ensure that workers are adequately trained and competent in confined space entry procedures. Provide specific training on the use of safety equipment, emergency procedures, and hazard recognition. Establish clear communication procedures, including radios or signals, to maintain contact with workers inside the confined space. Implement a buddy system to enhance communication and mutual assistance. Ensure proper ventilation to control atmospheric hazards. This may involve using forced air systems to supply fresh air and remove contaminants. Use gas detectors to continuously monitor the atmosphere for toxic gases, oxygen levels, and flammable substances. Establish predefined acceptable levels for atmospheric conditions and take immediate action if these levels are exceeded. Provide appropriate PPE, such as respiratory protection, harnesses, safety lines, and helmets. Ensure that all PPE is properly fitted, regularly inspected, and maintained. Develop a comprehensive emergency rescue plan, including procedures for retrieval of workers in case of an emergency. Train and equip a dedicated rescue team with the necessary skills and equipment. Isolate and lockout/tagout energy sources to prevent accidental activation of equipment within the confined space. Clearly communicate isolation procedures and ensure they are followed. Provide adequate lighting inside the confined space to ensure clear visibility for workers. Use explosion-proof lighting in environments where flammable substances are present. Implement a permit system for confined space entry. This includes obtaining proper authorization, documenting safety measures, and specifying entry conditions. Regularly review and reassess the confined space work environment, especially if conditions change during the work process. Conduct regular drills and training exercises to ensure that workers are familiar with emergency procedures and can respond effectively in case of an incident. Comply as per ADOSH COP-27.0"],"revisedProbability":1,"revisedSeverity":3},{"id":57,"activity":"Use of Generator","hazards":["Electrocution Fire, Loss of hearing capacity Personal Injury, Major and multiple injury Property damage"],"probability":4,"severity":3,"controls":["Provide bund wall and drip tray. Isolate the area. The cables are safely routed. Earthing to installed. Fire point to be provided Emergency shutdown procedures. Regular maintenance to be conducted. Do not remove noise protective measures. The generator should be operated with silencer. The exposure of workmen to high noise must have concern of allowable legal limit. Train workforce to maintain PPE. Maintain safe distance while working with heavy machineries if noisy. Comply as per ADOSH COP-36.0"],"revisedProbability":1,"revisedSeverity":3},{"id":58,"activity":"Installation sheet piles","hazards":["Inadequate design Failure of Shoring system, Failure of adjacent road and structure Inappropriate placement Personal Injury, Major and multiple injury Property damage"],"probability":4,"severity":3,"controls":["All shoring systems must be assembled and installed in accordance with the manufacturer's instructions and site- specific requirements as per method statement. All works are performed under competent supervision. Work activities are closely monitored. Sheet piling must be interlocked. Shoring system to be designed by competent Engineer. Ensure all support work is secure and that props and wedges are tight. All shoring systems must be checked regularly and maintained properly for the duration of the work. Check for visible over-stress, damage, leakage and non- alignment. Train all personal about MSRA. Inspections must be by a competent person. Pile extraction as per MSRA. Do not remove any cross struts before removing pile. Identify where 'short term stability' is being assumed when considering the stability of the excavation during extraction. Comply as per ADOSH COP-29.0 & 20.0"],"revisedProbability":1,"revisedSeverity":3},{"id":59,"activity":"Use of Hand Tools","hazards":["Unsafe operations and tools could cause workplace injuries. Major and minor injuries"],"probability":4,"severity":3,"controls":["Appropriate tools shall be used with damaged free condition. Train workmen to use hand tools safely. Minimum hand hold provision shall be in place. Safe and suitable provision of hand hold shovel must be used. Tools are stored in safe location if no work after cleaning. Rotten wood or unsuitable wedges on wooden hold shall not be used. Store the materials in structured way. Comply as per ADOSH COP-35.0"],"revisedProbability":1,"revisedSeverity":3},{"id":60,"activity":"Adverse Weather Condition","hazards":["Unauthorized and breaching can cause fatal and multiple injuries. Major injury, Personal injury& Material damage."],"probability":4,"severity":3,"controls":["Stay informed about upcoming weather conditions by regularly checking weather forecasts. Utilize reliable sources to receive timely updates. Establish a comprehensive weather emergency plan that includes protocols for different adverse conditions such as storms, extreme heat, cold, or heavy rainfall. Conduct regular inspections of the construction site to identify potential hazards related to adverse weather conditions. Address any issues promptly. Secure or dismantle temporary structures and materials that may be susceptible to wind, rain, or other adverse weather conditions. Ensure that construction equipment is properly maintained and inspected regularly. Secure equipment during inclement weather to prevent it from becoming a hazard. Adjust work schedules to minimize exposure to extreme weather conditions. Consider working during more favorable weather and avoiding work during severe conditions. Provide workers with appropriate protective clothing and gear for the specific weather conditions they may face, such as waterproof clothing, cold-weather gear, or sun protection. Train workers on the potential risks associated with adverse weather conditions and ensure they are aware of safety protocols and emergency procedures. Establish a reliable communication system for quick dissemination of weather-related information and emergency instructions. Ensure all workers are aware of the communication plan. Have a well-equipped first aid station on site and ensure that medical facilities are accessible in case of emergencies. Train workers in basic first aid. Monitor and address issues related to ground stability during adverse weather conditions, especially in areas prone to flooding, landslides, or soil erosion. Install effective drainage systems to prevent water accumulation on the construction site. Ensure that water runoff is directed away from excavation areas and structures. Establish wind speed guidelines for various construction activities. Suspend work if wind speeds exceed safe limits for certain tasks. Calibrate equipment sensitive to weather conditions, such as cranes and hoists, to ensure safe and accurate operation. Provide designated emergency shelter areas were workers can seek refuge during adverse weather conditions."],"revisedProbability":1,"revisedSeverity":3},{"id":61,"activity":"Dust","hazards":["Health hazards Occupational illness"],"probability":4,"severity":3,"controls":["Develop a comprehensive dust control plan that outlines specific measures to be taken on the construction site. Ensure all workers are familiar with the plan and adhere to its guidelines. Use water suppression methods such as water trucks, hoses, or sprinkler systems to dampen dusty areas. This helps to weigh down the dust particles, preventing them from becoming airborne. Stabilize exposed soil areas with vegetation, mulch, or soil binders to reduce the likelihood of soil erosion and dust generation. Install windbreaks, such as temporary fencing or barriers, to minimize the impact of wind on dust dispersion. Wind can carry dust over long distances. Cover piles of soil, sand, or other materials when they are not in use to prevent wind erosion and dust emission. Use tarps or other suitable covers. Employ construction equipment that is equipped with dust control features, such as water spray systems on crushers and drills. Provide workers with appropriate PPE, including dust masks or respirators, especially in areas where dust levels are high. Schedule regular watering of construction areas, especially during dry and windy conditions, to keep the soil moist and minimize dust. Plan and execute demolition activities carefully to minimize dust generation. Wet down materials before demolition and use controlled methods to avoid creating excessive dust. Use vacuum systems and sweeping equipment equipped with dust collection features to clean up dust and debris regularly. Implement traffic control measures to reduce vehicle speeds on unpaved surfaces, minimizing the generation of dust. Train workers on the importance of dust control measures and the proper use of equipment. Emphasize the health risks associated with exposure to airborne dust. Conduct regular inspections of the construction site to identify areas where dust control measures may need improvement. Address issues promptly."],"revisedProbability":1,"revisedSeverity":3},{"id":62,"activity":"Waste management","hazards":["Chemical Hazards Biological Hazards Fire and Explosion risk Sharp objects Noise exposure Accumulation of Dust Environmental Impact Improper handling and Sorting Inadequate use of PPE"],"probability":4,"severity":3,"controls":["Ensure that workers involved in waste management wear appropriate PPE, including gloves, safety boots, high-visibility clothing, and respiratory protection if needed. Provide comprehensive training for workers on proper waste handling procedures, the use of equipment, and the importance of safety. Promote awareness of potential hazards associated with different types of waste. Regularly inspect and maintain waste management equipment, such as trucks and containers, to ensure they are in good working condition. Train workers on proper manual handling techniques to minimize the risk of musculoskeletal injuries during the lifting and carrying of waste containers. Implement effective traffic control measures in waste collection areas to prevent accidents involving waste collection vehicles and other vehicles or pedestrians. Use signage, barricades, and flaggers as needed. Develop and communicate an emergency response plan for incidents such as spills, accidents, or hazardous material exposures. Ensure that workers are trained on emergency procedures. Clearly identify and segregate hazardous waste from non- hazardous waste. Install fire extinguishers at strategic locations in waste management facilities and vehicles. Provide adequate ventilation in indoor waste management facilities to prevent the build-up of harmful gases or fumes. Use exhaust systems where necessary. Label waste containers with appropriate hazard communication symbols and information. Implement measures to prevent cross-contamination of waste streams, especially when handling different types of waste. Use separate containers for different categories of waste. Provide lifting and handling equipment, such as forklifts or conveyor belts, to reduce manual handling and minimize the risk of injuries. Train workers on proper waste sorting procedures to separate recyclable materials from non-recyclable waste. Implement recycling programs to reduce the volume of waste sent to landfills. Ensure that waste is disposed of in accordance with local regulations and environmental standards. Regularly monitor and audit waste management practices to ensure compliance with safety regulations and environmental standards. Store waste containers securely to prevent spills, leaks, or unauthorized access. Ensure that storage areas are well-maintained and organized. Keep detailed records of waste management activities, including waste collection, transportation, and disposal."],"revisedProbability":1,"revisedSeverity":3},{"id":63,"activity":"Emergency Procedure","hazards":["Structural Instability Fire and Explosion Toxic Substance Release Electrical Hazards Falls and Trips Lack of Emergency Equipment Inadequate Training"],"probability":4,"severity":3,"controls":["Develop a detailed and site-specific emergency response plan that addresses potential hazards and scenarios. Clearly outline roles and responsibilities for emergency response teams and individuals. Establish reliable communication systems for alerting and notifying personnel in the event of an emergency. Ensure communication methods are diverse, including alarms, public address systems, radios, and other electronic communication devices. Maintain an updated list of emergency contacts, including local emergency services, key personnel, and external agencies. Clearly communicate emergency contact information to all relevant stakeholders. Conduct regular emergency drills to ensure that personnel are familiar with emergency procedures. Provide training on specific actions to take during various types of emergencies. Develop evacuation plans for different scenarios, including fire, chemical spills, or natural disasters. Clearly mark evacuation routes and assembly points. Ensure the availability and functionality of emergency equipment, such as fire extinguishers, first aid kits, emergency lighting, and evacuation tools. Regularly inspect and maintain emergency resources. Clearly mark emergency exits and ensure they are unobstructed. Conduct regular inspections of emergency exits to ensure they are functional. Designate assembly points where personnel should gather after evacuating. Ensure that assembly points are located in safe areas away from potential hazards. Provide first aid training to designated personnel. Establish procedures for medical response, including the activation of emergency medical services. Install emergency lighting systems to ensure visibility during power outages or low-light conditions. Regularly test and maintain emergency lighting systems. Develop shut down procedures for critical systems or equipment during emergencies to prevent further risks. Establish procedures for handling and containing hazardous materials in the event of a spill or release. Provide appropriate training and equipment for personnel dealing with hazardous materials. Include security measures in emergency procedures, especially in situations involving threats or unauthorized access. Coordinate with law enforcement if necessary. Use a centralized communication hub to provide updates and instructions. Regularly review and update emergency procedures based on changes in the workplace, personnel, or external factors. Conduct post-emergency debriefings to identify areas for improvement. Maintain detailed documentation of emergency procedures, drills, and responses. Use documentation for continuous improvement and compliance purposes."],"revisedProbability":1,"revisedSeverity":3},{"id":64,"activity":"Hollow Core Slab Installation","hazards":["Collision, Man/Machine interface Pinch Points Falling of materials from Trailer Load falling Load hitting with adjacent structures and personnel Overturing of mobile crane falling of personnel"],"probability":4,"severity":3,"controls":["Ensure Pre-Start briefing is conducted by supervisor prior to commence the activity Trailers shall be parked in designated laydown areas. Ensure adequate aisle is provided in material storage area for access and egress to retrieve materials. All lifting equipment and lifting accessories are inspected and certified by 3rd party company Accredited by ADM. Ensure all lifting equipment and lifting accessories are inspected and color coded/ Tag Displayed appropriately. Ensure ground adequately compacted inspected and approved for crane establishment. Ensure all lifting equipment and lifting accessory are inspected and color coded/ Tag Displayed appropriately. Ensure all personnel are properly trained in crane operations and Follow safe System of work. Adequate supervision by (NFT) tower crane specialist. Scissor Clamp Lifter: A third-party inspected scissor clamp lifter shall be used for lifting slabs up to 200 mm in thickness. While lifting HCS with scissors, ensure that safety chain beneath hollow core slab is fixed to prevent accidental fall down of HCS. Nylon web-Sling: A third-party inspected nylon web sling 6 tons shall be used for lifting slabs thicker than 200 mm and for lifting cut pieces of hollow core slabs, following safe choke lifting procedures. Hard Barricading as exclusion zone with flagman assigned and signboard displayed throughout the lifting area/lifting radius. HCS should be stacked in a safe height to prevent fall or damage materials. Please ensure that a wood block is placed under the heel to prevent the crowbar from slipping and to reduce the risk of injury to the hand. Offload the slabs and cut pieces in a designated, safe, and clear area with a firm, level foundation. Ensure barricade the HCS area and install appropriate signage if storage is required for an extended period. In all cases if a wind excess of 38 km/h (20.5) knots Work shall be immediately stopped, AS PER ADOSH-SF) CoP 34.0 - Safe Use of Lifting Equipment and Lifting Accessories. Use appropriate personal protective equipment (Hard Hat, Safety shoe, Hand Gloves, Safety Goggles and High Visibility) as per ADOSH-SF CoP 2.0 – Personal Protective Equipment."],"revisedProbability":1,"revisedSeverity":3},{"id":65,"activity":"Block Work","hazards":["Lack of safe access/egress Personnel injury Skin contacts with cement"],"probability":4,"severity":3,"controls":["All personnel shall complete EHS Induction prior mobilizing work at site Equipment inspection prior mobilization at site to ensure equipment fitness and readiness for work at site. Ensure that equipment’s/machineries are in good working condition and legal documents such as valid registration and fitness certificate of equipment are in place. Scaffold working platform should be constructed as per the standard procedures and relevant local authority requirements ADOSH COP 26.0 Working platforms should not be overloaded with blocks or personnel, which in turn might cause deflection of planks and eventually collapse of the working platform. Safe means of access must be provided. Provision of suitable equipment at site in line to work requirement Equipment shall be well maintained Alteration of equipment is not permitted Worker shall be competent for the operation of equipment Electrician shall ensure that electrical connections are done properly and the trip devices fitted to DB. The worker shall not wear any jewellery or watch while engaged to equipment to avoid contact. Equipment shall fit with emergency button Prestart work briefing to be conducted by the supervisor Provision of safe access/egress and proper lighting arrangements Health surveillance /monitoring to be conducted to the workers. Worker shall brief with the material handling and emergency response Respirator mask (N95) to be provided with workers engaged with activity in addition to compliance with mandatory PPE at site Eye wash station and hand washing facility to be provided in strategic location Workers shall wear well fitted coverall and gloves Provision of defined working station Working Area shall be isolated If grinder operation required, assessment shall be made such as identified trained personnel, proper workshop area and equipped with full PPE Guard rail system such as toe Board, mid and top rail must be in place. Scaffolding and working at height CoP 23.0"],"revisedProbability":1,"revisedSeverity":3},{"id":66,"activity":"PLASTERING WORKS","hazards":["Collapse of scaffold, fall of person and material, incomplete scaffold platform."],"probability":4,"severity":3,"controls":["Ensure that Scaffold platform should be fully boarded with planks and tied properly. Top rail, mid rail, Toe boards should be provided around the working platform. Safe access and egress should be provided to reach working platform. Cross bracing & transom supports should be provided for the scaffolds as per the requirement. Ensure the fully body harness with snatch hook should be provided for workforce. Scaffold tag system should be followed strictly. Avoid live electrical cables routed through Scaffolds. The operators of mechanical mixer and plastering machine should be certified by manufacturer (or) 3rd party. Any Alternation/modification of scaffold platform should be done by competent scaffolders under the close supervision of concern scaffold supervisor; the scaffold should be re‐ inspected by competent scaffold inspector. The color code of mechanical mixer and plastering machine should be followed quarterly basis. Ensure that stoppers should be provided on Scaffold platform to avoid fall of material while plastering Work. The scaffold above 10-meter height should be certified by 3rd party Ensure Strict compliance of ADOSH-SF CoP 23.0 Working at height. Ensure Strict Compliance with ADOSH-SF Code of Practice CoP 14.0 – Manual Handling and Ergonomics. Use appropriate personal protective equipment (Hard Hat, Safety Shoes Hand Gloves, Safety Goggles and High Visibility) as per ADOSH SF CoP 2.0 – Personal Protective Equipment."],"revisedProbability":1,"revisedSeverity":3},{"id":67,"activity":"Temporary Materials storage","hazards":["Slips, Trips, and Falls: Falling Materials: Sharp Edges & Tools: Heavy Lifting Injuries: Flammable Materials: Electrical Hazards: Weather Exposure: Chemical Spills: Manual Handling of Materials: Inadequate Space for Movement:"],"probability":4,"severity":3,"controls":["Ensure all walkways are clear of debris, and materials are properly stacked. Place warning signs and barriers where necessary. Conduct regular inspections of storage areas to identify potential hazards. Use forklifts or mechanical aids for handling heavy materials. Implement proper lifting techniques training for workers. Ensure materials are securely stacked and stored at appropriate heights. Store flammable materials away from heat sources and electrical equipment. Ensure fire extinguishers, fire alarms, and sprinkler systems are in place and functional. Conduct fire drills and training for employees on fire response procedures. Protect sensitive materials from extreme weather by storing them in sheltered areas. Ensure proper drainage around storage areas to prevent water accumulation and material degradation. Store chemicals in appropriate containers and ensure proper labeling. Provide spill kits and ensure workers are trained in spill response procedures. Provide appropriate PPE such as gloves, hard hats, and steel- toed boots for workers. Ensure all workers are trained in PPE usage and maintenance. Establish and communicate emergency evacuation routes in the event of fire or chemical spills. Maintain first-aid kits at accessible locations in the storage area. Ensure workers are trained in first aid and emergency procedures related to the specific hazards of the storage area. Ensure Strict Compliance with ADOSH-SF Code of Practice CoP 14.0 – Manual Handling and Ergonomics. Use appropriate personal protective equipment (Hard Hat, Safety Shoes Hand Gloves, Safety Goggles and High Visibility) as per ADOSH SF CoP 2.0 – Personal Protective Equipment."],"revisedProbability":1,"revisedSeverity":3},{"id":68,"activity":"Working on roof","hazards":["Falls from Height Slips, Trips, and Falls on Roof Surface Falling Objects Weather Conditions Structural Integrity of Roof Electrical Hazards Manual Handling Injuries Confined Spaces (Roof Entrances)"],"probability":4,"severity":3,"controls":["Provide and ensure the use of personal fall protection equipment (e.g., harnesses, lanyards, and anchor points). Install guardrails or safety nets at roof edges. Use safety harnesses and secure lanyards when working near open edges or skylights. Ensure that the roof surface is clean and free of debris. Provide workers with proper non-slip footwear with adequate grip. Use temporary walkways or scaffolding to ensure safe movement across the roof. Ensure that tools and materials are secured with tool lanyards to prevent falling. Store tools and materials away from roof edges, or use safety barriers to prevent items from falling. Monitor weather conditions and suspend work if high winds, rain, or extreme temperatures make working unsafe. Provide weather-appropriate clothing for workers to protect against extreme temperatures. Conduct a structural assessment of the roof before allowing work to begin to ensure it can support workers and equipment. Perform regular roof inspections to identify and address any weak spots or damage. Provide workers with proper electrical safety training and ensure that they are aware of live wire locations. Provide workers with mechanical aids or lifting equipment to minimize physical strain. Train workers in safe lifting techniques and encourage team lifting for heavy or bulky items. Ensure proper ventilation and accessibility to roof entrances or hatches. Provide confined space training for workers who may need to access confined roof spaces. Falls: Have a rescue plan in place and ensure that all workers are trained in rescue techniques. Weather Emergencies: Implement procedures for emergency evacuation in case of sudden weather changes. Electrical Incidents: Have emergency contact numbers for electricians and ensure that workers are trained to respond to electrical incidents."],"revisedProbability":1,"revisedSeverity":3},{"id":69,"activity":"Air compressor","hazards":["Noise Pressure-related Hazards Airborne Contaminants Fire Hazard Electrical Hazards Slip, Trip, and Fall Hazards Compressed Air Leaks"],"probability":4,"severity":3,"controls":["Ensure that air compressors are equipped with safety guards around moving parts. Perform regular maintenance to check for any loose or worn parts. Provide training on safe operation and servicing of compressors. Provide workers with hearing protection, such as earplugs or earmuffs. Regularly monitor noise levels and implement noise-reducing measures, such as soundproof enclosures. Ensure that pressure relief valves are functional to prevent over- pressurization. Regularly check hoses and fittings for wear or damage. Set and maintain proper operating pressure according to manufacturer’s guidelines. Use proper filtration for the intake air to prevent the introduction of contaminants. Inspect and replace filters as needed to ensure clean, dry air is provided. Provide workers with eye protection and respirators if necessary. Ensure that air compressors are properly ventilated to avoid overheating. Regularly check for any electrical or mechanical faults that could lead to sparks or fires. Keep air compressors away from flammable materials and install fire extinguishers in the work area. Ensure that air compressors are properly grounded and use safety switches. Inspect power cords, plugs, and electrical connections for signs of wear or damage. Provide workers with training in electrical safety when working with compressors. Secure air compressor hoses and cables to prevent tripping hazards. Keep the area around the compressor dry and free of debris. Install warning signs in areas with wet surfaces or tripping hazards. Regularly inspect and maintain hoses, fittings, and tanks to ensure no leaks. Replace worn or damaged hoses and fittings immediately. Train workers on the safe operation of compressed air equipment. In the event of a fire: Evacuate the area immediately and use fire extinguishers or the emergency services as needed. In case of electrical shock: Cut off the power supply, administer first aid, and call emergency services. If a pressure release occurs: Ensure workers are clear of the area and allow the compressor to cool before inspecting it."],"revisedProbability":1,"revisedSeverity":3},{"id":70,"activity":"Manual Handling","hazards":["Lifting Heavy Loads Repetitive Lifting or Twisting Carrying or Pushing Loads Incorrect Posture Slips, Trips, and Falls Manual Handling of Sharp or Hazardous Materials Inadequate Training"],"probability":4,"severity":3,"controls":["Provide workers with manual handling training to ensure they understand proper lifting techniques (e.g., bending the knees, keeping the back straight). Encourage workers to assess the load before lifting and determine if mechanical aids are needed (e.g., forklifts, pallet jacks). Implement job rotation to allow workers to alternate between tasks and avoid repetitive movements for extended periods. Encourage regular breaks to reduce the risk of repetitive strain injuries. Provide and encourage the use of lifting aids (e.g., trolleys, forklifts, hoists) to handle heavy or awkward loads. Ensure that the equipment is properly maintained and easily accessible. Set up workstations that promote correct posture (e.g., adjustable tables or lifting platforms). Advise workers to keep loads close to their bodies and avoid twisting while lifting. Maintain clear walkways and ensure that areas are free from obstacles. Ensure that floors are clean and dry, and that spillages are cleaned immediately. Use non-slip footwear for workers when manual handling tasks are being performed in slippery conditions. Provide appropriate PPE (e.g., gloves, steel-toed boots, goggles) for workers handling hazardous or sharp materials. Ensure that safety procedures are in place for handling chemicals or materials with sharp edges. Provide manual handling training for all workers to educate them on safe lifting techniques, recognizing hazards, and using lifting aids. Conduct refresher courses regularly to keep safety practices top of mind. In the event of an injury: Provide first aid immediately and seek medical attention if necessary. For hazardous material exposure: Follow established procedures for chemical spills or sharp object injuries, including first aid and emergency services contact. For a slip or fall: Ensure the worker is attended to immediately and evaluate the need for further medical treatment."],"revisedProbability":1,"revisedSeverity":3},{"id":71,"activity":"Working at height","hazards":["Falls from Height Falling Objects Fragile or Unstable Surfaces Unstable Ladders or Scaffolding Adverse Weather Conditions Electrical Hazards Fatigue and Lack of Concentration"],"probability":4,"severity":3,"controls":["Ensure guardrails and toe boards are installed on all work platforms. Workers must wear Personal Fall Protection Equipment (PFPE), including full-body harnesses and lanyards. Use fall arrest systems, such as safety nets, where necessary. Inspect ladders and scaffolding before use to ensure they are in good condition. Secure ladders at the correct angle (4:1 rule) and ensure they are on stable, level ground. Ensure scaffolding is properly erected by competent personnel and includes guardrails and toe boards. Use tool lanyards to secure tools and prevent them from falling. Install safety netting or barriers to catch falling objects. Workers below must wear hard hats and avoid unnecessary entry into high-risk zones. Conduct structural assessments before working on roofs or platforms. Use crawling boards or walkways to distribute weight safely. Clearly mark fragile areas with warning signs. Suspend work at height during strong winds, rain, or icy conditions. Ensure non-slip footwear is worn by all workers. Reschedule tasks to avoid extreme weather conditions when possible. Maintain a safe distance from overhead power lines. Use non-conductive ladders (fiberglass instead of metal) when working near electrical hazards. De-energize electrical sources or install protective barriers before work begins. Implement rotational shifts to prevent overexertion. Provide regular breaks for workers engaged in physically demanding tasks. Conduct regular training sessions on working at height safety, fall prevention, and emergency procedures. Ensure Follow Code of Practice CoP 23.0 – Working at Height Use appropriate personal protective equipment (Hard Hat, Safety Shoes Hand Gloves, Safety Goggles and High Visibility) as per ADOSH SF CoP 2.0 – Personal Protective Equipment."],"revisedProbability":1,"revisedSeverity":3},{"id":72,"activity":"Scaffolding","hazards":["Scaffold Collapse Falling Objects Unstable Ground or Foundation Electrical Hazards Weather Conditions Poor Access & Egress Lack of Training"],"probability":4,"severity":3,"controls":["Install guardrails, toe boards, and midrails on all scaffolding levels. Workers must wear personal fall protection equipment (PFPE), including harnesses where necessary. Maintain three points of contact when climbing ladders or moving on scaffolding. Ensure scaffolding is assembled by certified personnel following manufacturer guidelines. Conduct pre-use inspections and regular safety checks to identify defects or weaknesses. Never exceed the maximum load capacity of scaffolding structures. Use toe boards, tool lanyards, and netting to prevent items from falling. Workers below scaffolding must wear hard hats and avoid working directly under scaffold areas when possible. Secure all loose materials to prevent accidental drops. Erect scaffolding on firm, level ground with base plates or screw jacks for stability. Avoid setting up scaffolding near trenches, holes, or soft ground. Use outriggers where necessary to stabilize scaffolding. Maintain a safe distance (minimum 3m / 10 feet) from overhead power lines. Use non-conductive scaffolding materials (e.g., fiberglass) when working near electrical sources. Ensure all electrical tools used on scaffolding have ground fault circuit interrupters (GFCI). Suspend work during strong winds, heavy rain, snow, or icy conditions. Ensure workers wear non-slip footwear. Clear snow, ice, or water from scaffolding platforms before starting work. Use secured ladders, stair towers, or scaffold-specific access points instead of makeshift entry points. Ensure ladders extend at least 1 meter (3 feet) above the scaffold platform for safe access. Keep all access points free from obstructions. Ensure all workers are trained and certified in scaffolding erection, use, and hazard awareness. Conduct regular toolbox talks to reinforce scaffolding safety practices. Assign a competent person to inspect scaffolding daily before work begins. Ensure Follow Code of Practice CoP 23.0 – Working at Height Ensure Follow Code of Practice CoP 26.0 – Scaffolding Use appropriate personal protective equipment (Hard Hat, Safety Shoes Hand Gloves, Safety Goggles and High Visibility) as per ADOSH SF CoP 2.0 – Personal Protective Equipment."],"revisedProbability":1,"revisedSeverity":3},{"id":73,"activity":"Compressed gas","hazards":["Explosion & Fire Risk Gas Leak & Asphyxiation Cylinder Rupture & Projectile Hazard Toxic or Corrosive Exposure Manual Handling Injuries Incompatible Gas Reactions"],"probability":4,"severity":3,"controls":["Store cylinders in well-ventilated areas, away from ignition sources. Keep flammable and oxidizing gases separate.","Ensure fire extinguishers (CO₂, dry powder) are available near storage areas. Inspect cylinders for leaks before use using soapy water (not flames). Keep storage and usage areas well-ventilated to prevent gas accumulation. Use gas detectors and alarms in confined spaces. Always secure cylinders upright using chains or brackets. Store away from extreme heat and direct sunlight. Never drop or roll cylinders; use trolleys for transportation. Ensure safety data sheets (SDS) are available for all gases in use. Train workers in emergency response for gas leaks. Use mechanical aids (trolleys, hoists) to transport heavy cylinders. Train workers on proper lifting techniques. Never lift cylinders by their valve or cap. Store flammable and oxidizing gases separately. Clearly label all cylinders and follow color-coding guidelines. Ensure proper valve caps are in place when cylinders are not in use. Ensure Strictly Follow Code of Practice CoP 49.0 – Compressed Gases and Air. Ensure Strictly Follow (Hard Hat, Safety Shoes Hand Gloves, Safety Goggles and High Visibility) as per ADOSH SF CoP 2.0 – Personal Protective Equipment."],"revisedProbability":1,"revisedSeverity":3},{"id":74,"activity":"Testing & Commissioning","hazards":["Electrical Hazards Mechanical Hazards Fire & Explosion Risks High-Pressure Systems Hazardous Chemicals & Gases Confined Space Hazards Noise & Vibration Exposure Slips, Trips & Falls"],"probability":4,"severity":3,"controls":["Lockout/Tagout (LOTO) procedures must be followed before testing live circuits. Use insulated tools and PPE (gloves, face shields, arc-rated clothing). Ensure ground fault protection and proper circuit insulation. Install machine guards and barrier zones to prevent accidental contact. Keep hands, loose clothing, and tools away from moving parts. Test systems in a controlled environment with safety protocols in place. Ensure proper ventilation to prevent gas accumulation. Keep fire extinguishers nearby and train personnel in their use. Conduct thermal imaging inspections to detect overheating components. Use pressure relief valves and ensure systems are tested at rated capacity. Keep personnel at a safe distance during pressure testing. Inspect pipes, hoses, and fittings for leaks or damage before operation. Store and handle chemicals according to MSDS guidelines. Use gas detectors in areas where leaks are possible. Ensure emergency showers and eyewash stations are available. Conduct gas monitoring before entry into confined spaces. Implement a permit-to-work system and ensure an emergency rescue plan is in place. Provide adequate ventilation and use breathing apparatus if necessary. Use hearing protection (earplugs/muffs) in high-noise areas. Limit exposure time to vibrating tools and machinery. Conduct regular audiometric testing for workers exposed to high noise levels. Keep work areas clean and free from obstructions. Mark cables and hoses clearly to prevent tripping hazards. Use anti-slip mats where necessary and maintain good lighting."],"revisedProbability":1,"revisedSeverity":3},{"id":75,"activity":"Live Electrical","hazards":["Electric Shock & Electrocution Arc Flash & Arc Blast Fire & Explosion Equipment Damage & System Failure Slips, Trips & Falls Confined Space & Ventilation Risks"],"probability":4,"severity":3,"controls":["Live work should be avoided whenever possible – de- energize circuits before maintenance. If live work is necessary, follow strict permit-to-work procedures. Ensure clear work area free of trip hazards, combustible materials, and unauthorized personnel. Use Lockout/Tagout (LOTO) procedures to prevent accidental re-energization. Maintain safe approach distances based on voltage level. Inspect and test circuits before handling using properly rated equipment. Wear insulated gloves, arc-rated clothing, safety boots, and face shields. Use fire-resistant PPE to protect against arc flash. Ensure workers have electrically rated tools with proper insulation. Keep flammable materials away from electrical panels and equipment. Use intrinsically safe tools in explosive environments.","Ensure fire extinguishers (CO₂, dry powder) are available nearby. Only qualified electricians should perform live work. Conduct regular training on electrical hazards, emergency response, and safe work practices. Supervisors must verify worker competency and risk awareness before live work begins. Keep work areas dry to prevent electrocution risks. Properly route and secure cables to avoid trip hazards. Use adequate lighting to improve visibility. Ensure Strictly Follow (Hard Hat, Safety Shoes Hand Gloves, Safety Goggles and High Visibility) as per ADOSH SF CoP 2.0 – Personal Protective Equipment."],"revisedProbability":1,"revisedSeverity":3},{"id":76,"activity":"Live Sewage","hazards":["Exposure to Biological Hazards Toxic Gas Exposure Slips, Trips & Falls Drowning & Entrapment Chemical Exposure Electrical Confined Space"],"probability":4,"severity":3,"controls":["Wear impermeable gloves, coveralls, rubber boots, safety goggles, and face shields. Use respiratory protection (masks, SCBA) in areas with toxic gas risks. Provide handwashing stations and decontamination procedures after work. Ensure workers are vaccinated (Hepatitis A, Tetanus, Typhoid) before sewage work. Minimize direct contact with sewage by using long-handled tools where possible. Provide hand sanitizer and disinfectants for hygiene.","Use gas detectors to monitor hydrogen sulfide (H₂S), methane (CH₄), and oxygen levels before entry. Ensure forced ventilation in confined spaces to prevent gas buildup. Establish an emergency rescue plan for gas exposure incidents. Install guardrails, warning signs, and barriers around open pits or sewage areas. Maintain good lighting in work areas. Require workers to wear non-slip footwear. Provide Material Safety Data Sheets (MSDS) for all chemicals used in sewage treatment. Use chemical-resistant gloves and goggles when handling cleaning agents. Store chemicals in properly labeled containers away from sewage areas. Ensure power tools are waterproof and insulated. De-energize electrical equipment before work in wet areas. Use ground-fault circuit interrupters (GFCI) for electrical safety. Implement a permit-to-work system for entry into confined spaces. Assign a trained standby worker with rescue equipment at all times. Ensure workers are trained in confined space entry and emergency evacuation. Ensure Strictly Follow (Hard Hat, Safety Shoes Hand Gloves, Safety Goggles and High Visibility) as per ADOSH SF CoP 2.0 – Personal Protective Equipment."],"revisedProbability":1,"revisedSeverity":3},{"id":77,"activity":"Materials Shifting","hazards":["Manual Handling Injuries Falling Materials Slips, Trips & Falls Equipment & Machinery Exposure to Hazardous Substances Traffic & Pedestrian"],"probability":4,"severity":3,"controls":["Conduct pre-task risk assessments before shifting materials. Use mechanical aids (forklifts, hoists, trolleys, conveyor belts) whenever possible. Ensure clear and designated pathways for material movement. Train workers on proper lifting techniques (bend knees, keep back straight, lift with legs). Avoid twisting the body while lifting heavy materials. Use team lifting for heavy or bulky loads. Only trained and authorized personnel should operate forklifts, cranes, and lifting equipment. Perform regular maintenance and inspections of material- handling machinery. Use signalers and warning signs in high-traffic areas. Secure loads properly with straps, pallets, or restraints before moving. Stack materials evenly and within height limits to prevent toppling. Wear hard hats and steel-toe boots in material handling areas. Keep floors clear of obstacles and spills to prevent slips and trips. Store materials in designated areas away from walkways and exits. Ensure good lighting and visibility in shifting areas. Establish separate pedestrian and vehicle zones in the worksite. Use warning alarms, mirrors, and spotters in areas with limited visibility. Enforce low-speed limits for material-handling vehicles. Provide and enforce the use of gloves, safety boots, reflective vests, and eye protection. Require workers to wear hearing protection if working in noisy environments. Ensure Strictly Follow Code of Practice CoP 1.0 - Hazardous Materials Ensure Strictly Follow (Hard Hat, Safety Shoes Hand Gloves, Safety Goggles and High Visibility) as per ADOSH SF CoP 2.0 – Personal Protective Equipment."],"revisedProbability":1,"revisedSeverity":3},{"id":78,"activity":"LOTO Procedure","hazards":["Unexpected Equipment Start-Up Electrical Hazards Stored Energy Release Inadequate Training & Awareness Confined Space Hazards Communication Failure"],"probability":4,"severity":3,"controls":["Follow standardized Lockout/Tagout procedures for each piece of equipment. Ensure LOTO devices (locks, tags, hasps) are used correctly. Assign only authorized personnel to perform LOTO procedures. De-energize all power sources (electrical, hydraulic, pneumatic, mechanical) before work begins. Use testing devices (multimeters, voltage detectors) to confirm zero energy state. Ground and insulate all electrical components before servicing. Discharge or block hydraulic and pneumatic pressure before servicing. Secure spring-loaded mechanisms to prevent sudden movement. Release steam, chemicals, or gas pressure safely. Conduct regular training on LOTO procedures and hazard awareness. Provide clear written instructions on LOTO steps for each machine. Require LOTO refresher training for all workers annually. Use standardized LOTO tags with clear worker information. Ensure team communication before removing any lock or tag. Appoint a supervisor or LOTO coordinator to verify compliance. Provide insulated gloves, face shields, arc-rated clothing, and safety footwear. Use hearing protection if working near high-noise machinery. Ensure workers handling chemicals wear chemical-resistant gloves. Have emergency shutoff procedures posted near equipment. Train workers in first aid, CPR, and electrical rescue procedures. Keep fire extinguishers and spill kits readily available. Ensure Strictly Follow (Hard Hat, Safety Shoes Hand Gloves, Safety Goggles and High Visibility) as per ADOSH SF CoP 2.0 – Personal Protective Equipment."],"revisedProbability":1,"revisedSeverity":3},{"id":79,"activity":"Material Storage","hazards":["Falling Materials Fire Hazards Slips, Trips & Falls Chemical Hazards Manual Handling Injuries Structural Failure Pest Infestation"],"probability":4,"severity":3,"controls":["Stack materials securely and evenly to prevent tipping. Store heavier items at the bottom and lighter items on top. Use pallets, shelving, or racks designed for specific materials. Store flammable materials in designated areas, away from ignition sources. Install fire extinguishers, smoke detectors, and sprinklers in storage areas. Ensure adequate ventilation to reduce fire risk. Keep storage areas clean and free from obstructions. Maintain clear walkways to prevent tripping hazards. Implement regular inspections to ensure proper storage practices. Store chemicals in properly labeled, sealed containers. Separate incompatible chemicals (e.g., acids and bases) to prevent reactions. Provide spill containment systems and proper ventilation. Train workers in proper lifting techniques (bend knees, keep back straight). Use mechanical aids (forklifts, dollies, cranes) for heavy items. Require team lifting for bulky or heavy loads. Ensure storage racks and shelves are stable and properly installed. Conduct regular inspections for signs of damage or overloading. Repair or replace damaged storage structures immediately. Store materials off the ground and away from walls to prevent pest hiding spots. Regularly inspect for signs of rodents or insects. Implement proper waste disposal and sanitation to reduce pest attraction. Require gloves, safety boots, and hard hats when handling materials. Provide dust masks or respirators when dealing with fine particles or chemicals Ensure Strictly Follow (Hard Hat, Safety Shoes Hand Gloves, Safety Goggles and High Visibility) as per ADOSH SF CoP 2.0 – Personal Protective Equipment."],"revisedProbability":1,"revisedSeverity":3},{"id":80,"activity":"Repairing Work (Mason, Carp, Elect.)","hazards":["Falling Objects Electrical Hazards (for Electrical Work) Cuts and Abrasions (for Carpentry and Masonry) Strains and Sprains (Manual Handling) Falls from Heights Tool-related Injuries Exposure to Hazardous Materials Fire Noise"],"probability":4,"severity":3,"controls":["Ensure tools are maintained and inspected regularly. Use the correct tool for each task to reduce the risk of injury. Provide training on safe tool handling and proper techniques for electrical, masonry, and carpentry work. De-energize electrical circuits before work begins. Use insulated tools and wear rubber gloves when working near live circuits. Install lockout/tagout (LOTO) systems to prevent accidental energization. Ensure all electrical work is conducted by qualified personnel. Wear safety glasses, gloves, and steel-toed boots when handling materials or tools. Use hearing protection (ear plugs or earmuffs) when working with noisy tools. Wear fall protection (harnesses, lanyards) when working at height. Use dust masks or respirators if handling hazardous materials or working in dusty environments. Train workers in proper lifting techniques (bend knees, lift with legs). Use mechanical lifting aids (hoists, dollies, forklifts) to move heavy materials. Ensure materials are stored at a convenient height to minimize the need for lifting. Ensure ladders are stable and have non-slip feet. Use guardrails or fall arrest systems when working on scaffolds or roofs. Ensure scaffolding is properly installed and inspected for stability. Keep walkways clear of obstructions to prevent tripping. Identify hazardous materials (e.g., asbestos, lead paint, etc.) before starting work. Use appropriate containment methods (e.g., plastic sheeting) when working with hazardous materials. Dispose of hazardous waste in designated containers and follow local regulations. Remove or cover flammable materials near hot work areas. Have fire extinguishers available and ensure personnel are trained on their use. Keep a fire watch during and after welding, cutting, or any work that may produce sparks. Limit exposure to noisy work by using sound barriers or isolating high-noise areas. Ensure all workers wear hearing protection when using loud equipment. Ensure Strictly Follow (Hard Hat, Safety Shoes Hand Gloves, Safety Goggles and High Visibility) as per ADOSH SF CoP 2.0 – Personal Protective Equipment."],"revisedProbability":1,"revisedSeverity":3},{"id":81,"activity":"Coshh Handling","hazards":["Exposure to Hazardous Chemicals Spills and Leaks Chemical Reactions Inadequate Ventilation Manual Handling of Chemicals Lack of Personal Protective Equipment (PPE) Fire and Explosion Hazards"],"probability":4,"severity":3,"controls":["Conduct a COSHH risk assessment for all chemicals used in the workplace. Label all chemicals clearly with their hazards and safety information. Maintain Material Safety Data Sheets (MSDS) for all chemicals. Store chemicals in properly labeled, secure containers in well- ventilated areas. Separate incompatible chemicals to prevent reactions or leaks (e.g., acids from bases). Use secondary containment (e.g., trays, bunds) to catch potential spills. Ensure areas where chemicals are used or stored have adequate ventilation (e.g., fume hoods, exhaust fans). In confined spaces, use local exhaust ventilation to remove harmful fumes. Ensure workers wear the correct PPE, including gloves, goggles, aprons, and respirators when handling chemicals. Provide chemical-resistant clothing when necessary. Inspect and maintain PPE regularly to ensure effectiveness. Provide spill kits for handling hazardous materials and ensure workers are trained to use them. Contain and neutralize spills immediately to prevent exposure or environmental contamination. Dispose of waste chemicals properly according to environmental regulations. Use mechanical aids (e.g., trolleys, forklifts) to move heavy chemical containers. Train workers in correct manual handling techniques to prevent injury. Store chemicals at waist height to minimize lifting and bending. Store flammable chemicals away from sources of ignition. Use explosion-proof equipment and electrical fittings in areas with flammable substances.","Install fire extinguishers (e.g., CO₂, foam) and ensure workers are trained on their use. Provide COSHH training for all workers handling hazardous substances, focusing on correct handling procedures, emergency actions, and PPE usage. Hold regular refresher courses to ensure continued awareness and compliance. Ensure Strictly Follow (Hard Hat, Safety Shoes Hand Gloves, Safety Goggles and High Visibility) as per ADOSH SF CoP 2.0 – Personal Protective Equipment."],"revisedProbability":1,"revisedSeverity":3},{"id":82,"activity":"Tower Crane Maintenance","hazards":["Mechanical Failure During Maintenance Falling Objects Electrocution Working at Heights Manual Handling Injuries Crushed by Crane Components Fire Hazards Environmental Hazards (Weather Conditions) Inadequate PPE Use"],"probability":4,"severity":3,"controls":["Ensure all crane components are inspected regularly, including the boom, mast, hoists, cables, and gears. Replace worn-out or damaged parts before they cause failure. Follow the manufacturer’s maintenance guidelines for repairs and servicing. Ensure regular lubrication of moving parts to prevent friction and wear. Ensure tools and materials are securely stored and not let loose during maintenance at height. Use tool lanyards to prevent objects from falling. Install edge protection or safety nets around maintenance areas to catch any falling items. Isolate electrical systems and ensure the crane is de- energized before starting maintenance. Use lockout/tagout (LOTO) procedures to prevent accidental re- energization. Use insulated tools and wear appropriate PPE (e.g., rubber gloves) when working on electrical components. Ensure guardrails, safety nets, or personal fall arrest systems (harnesses, lanyards) are in place when working at height. Use approved scaffolding or elevated work platforms to provide safe access to high crane parts. Train workers on safe climbing techniques and proper use of fall protection equipment. Provide training in proper lifting techniques and safe handling practices. Use mechanical lifting aids (e.g., hoists, cranes, trolleys) for lifting heavy or awkward components. Store heavy components at waist height to minimize the need for lifting. Ensure sufficient workers are available for team lifts when necessary. Implement LOTO procedures before starting any maintenance work on the crane. Ensure all personnel are aware of and comply with LOTO protocols. Test equipment after lockout to ensure it cannot be operated during maintenance. Identify and remove flammable materials (e.g., fuels, oils) from the maintenance area before beginning work. Use fire-resistant tools and materials when welding, grinding, or cutting on the crane.","Keep fire extinguishers (CO₂ or powder-based) easily accessible near the maintenance area. Avoid maintenance work during severe weather conditions (e.g., strong winds, heavy rain, lightning). Monitor weather forecasts and stop work immediately if conditions become unsafe. Secure any loose materials or equipment that could be affected by the wind. Ensure all workers wear appropriate PPE, including hard hats, gloves, safety boots, high-visibility clothing, and fall protection gear. Use hearing protection if working near noisy crane components. Provide eye protection (safety goggles) for workers involved in cutting or grinding tasks. Ensure Follow Code of Practice 23.0 working at height Ensure Strictly Follow (Hard Hat, Safety Shoes Hand Gloves, Safety Goggles and High Visibility) as per ADOSH SF CoP 2.0 – Personal Protective Equipment."],"revisedProbability":1,"revisedSeverity":3},{"id":83,"activity":"Vehicle Maintenance","hazards":["Mechanical Failures During Maintenance Lifting and Handling of Vehicle Parts Exposure to Hazardous Substances (Fuel, Oil, etc.) Fire Hazards Slips, Trips, and Falls Electrocution During Electrical Maintenance Working in Confined Spaces High-Pressure Systems (Tires, Brakes, etc.) Inadequate Personal Protective Equipment (PPE)"],"probability":4,"severity":3,"controls":["Ensure vehicles are fully isolated (e.g., ignition turned off, battery disconnected) before starting maintenance work. Inspect and replace worn or damaged parts regularly to prevent failure during maintenance. Follow the vehicle manufacturer’s maintenance instructions and recommended procedures. Use appropriate lifting equipment (e.g., hoists, jacks, trolleys) for heavy components such as engines or transmissions. Team lifts should be used for heavy or awkward components, ensuring at least two workers are involved in lifting. Provide manual handling training for workers on proper lifting techniques to prevent strain or injury. Always store fuels, oils, and other vehicle fluids in secure, clearly labeled containers to prevent spills. Ensure workers use proper PPE, such as gloves, goggles, and aprons, when handling hazardous substances. Clean up spills immediately using appropriate absorbent materials, and dispose of waste fluids in accordance with regulations. Store flammable materials (fuels, oils) away from sources of heat or ignition. Use spark-proof tools when working near fuel systems or areas that could pose a fire hazard. Install fire extinguishers near work areas, and ensure workers are trained to use them (CO₂ for electrical fires, foam for fuel fires). Ensure the work area is well-lit to avoid accidents. Clean up spills immediately and use absorbent materials on oily or greasy floors. Maintain clear walkways free from tools, parts, and debris to reduce the risk of tripping. Isolate the electrical system by disconnecting the battery or using lockout/tagout (LOTO) procedures before working on electrical components. Use insulated tools and wear rubber gloves when working with electrical systems. Inspect electrical wiring regularly to prevent faults or short circuits that could lead to electrocution. Ensure adequate ventilation in confined spaces and ensure emergency exits are unobstructed. Workers should wear respirators if required, and a buddy system should be in place to monitor workers in confined spaces. Implement confined space entry procedures and ensure all workers are trained in these procedures. Depressurize systems such as tire compressors, brake lines, or hydraulic systems before maintenance begins. Use safety cages or shields when working with high-pressure equipment to prevent injury from sudden releases. Inspect pressure release valves and other safety mechanisms on high- pressure systems to ensure proper functioning. Ensure all workers wear appropriate PPE for the task, including gloves, goggles, protective clothing, and hearing protection. Use high-visibility clothing when working in areas with vehicle movement. Ensure Strictly Follow (Hard Hat, Safety Shoes Hand Gloves, Safety Goggles and High Visibility) as per ADOSH SF CoP 2.0 – Personal Protective Equipment."],"revisedProbability":1,"revisedSeverity":3},{"id":84,"activity":"Man, Machine Interface","hazards":["Inadequate User Training Poor Machine Design/Ergonomics Human Error Interface Confusion Machine Malfunction Electrical Hazards Equipment Overload Machine Start-Up or Shutdown Failures Poor Communication Between Operators and Machines"],"probability":4,"severity":3,"controls":["Ensure that all operators receive comprehensive training on machine operation, controls, and safety procedures. Provide refresher training periodically to address new updates or changes in machine technology or processes. Implement a competency-based assessment before operators are allowed to work on machinery independently. Provide adjustable seats, control panels, and display to accommodate a range of operator sizes and preferences. Include clear labeling and intuitive layouts on all machine interfaces to improve ease of use and reduce operator errors. Design machines with fail-safe mechanisms that help prevent accidents due to operator error (e.g., emergency stops, alarms, automated safety checks). Encourage a culture of safety, including rest breaks, to reduce fatigue-related errors. Provide clear and concise standard operating procedures (SOPs) for all operators, emphasizing safety and error prevention. Ensure that the user interface (UI) is clear, with simplified controls and intuitive displays for easy interpretation. Use color-coded indicators and audible alarms to signal potential machine faults or hazards. Provide feedback systems (e.g., visual or tactile) to indicate machine status, errors, or required actions. Implement a routine maintenance schedule to ensure machines are in good working condition. Ensure that critical components are regularly inspected and replaced before failure can occur. Use predictive maintenance techniques where feasible to identify potential issues before they lead to machine breakdown. Isolate electrical systems before maintenance or repair work begins. Ensure all machines are properly grounded and wired according to safety standards. Use insulated tools and wear PPE (e.g., rubber gloves) when working on electrical components of the machines. Conduct regular electrical system inspections to identify and resolve potential hazards. Set clear limits for load capacity and ensure machines are calibrated to operate within those limits. Install overload alarms or automatic shut-off systems to prevent damage to the machine or injury to the operator in case of overload. Train operators to recognize signs of overloading and instruct them on corrective actions. Implement and ensure strict adherence to lockout/tagout (LOTO) procedures during machine startup, shutdown, or maintenance. Ensure that all emergency stop buttons and safety interlocks are operational before starting the machine. Test startup and shutdown procedures regularly to ensure that no malfunctions occur during these phases. Use audible and visual signals to ensure clear communication between operators and machines. In automated or semi-automated systems, ensure that the machine provides real-time feedback to the operator, such as alerts for system malfunctions or maintenance needs. Install warning lights, alarms, or screen prompts that indicate machine status or require operator intervention"],"revisedProbability":1,"revisedSeverity":3},{"id":85,"activity":"Vehicle Parking","hazards":["Inadequate Parking Space or Poor Layout Poor Visibility Pedestrian-Vehicle Interaction Unstable or Sloping Surfaces Poor Signage and Markings Speeding and Reckless Driving Vehicle Fires or Fuel Leaks Theft or Unauthorized Access Emergency Vehicle Access Blockage"],"probability":4,"severity":3,"controls":["Designate separate entry and exit points to prevent congestion. Clearly mark parking bays, loading zones, and restricted areas. Allocate reserved parking spaces for emergency vehicles, disabled persons, and visitors. Install adequate lighting in parking areas, especially in blind spots and corners. Ensure that mirrors and cameras are installed in areas with limited visibility. Encourage vehicles to use hazard lights while reversing in busy zones. Establish clearly marked pedestrian walkways separate from vehicle paths. Install speed bumps and enforce a low-speed limit within parking areas. Encourage drivers to check mirrors and sound the horn when reversing in crowded areas. Ensure flat and even surfaces for parking zones to prevent rollaway risks. Install wheel stops and chocks for heavy vehicles to prevent unintended movement. Place clear, reflective signs for speed limits, exits, and directional guidance. Regularly maintain and repaint road markings to ensure visibility. Implement one-way traffic flow in congested areas to prevent collisions. Enforce a strict speed limit (e.g., 10-15 km/h) within parking zones. Use speed bumps, barriers, or rumble strips to slow down vehicles. Prohibit fueling or major repairs in parking areas. Install fire extinguishers at key locations in the parking lot. Conduct regular vehicle maintenance checks to detect leaks before parking. Use access control systems like barriers, gates, or security personnel. Provide adequate lighting to deter theft and unauthorized access. Keep fire lanes and emergency access points clear at all times. Install bollards or barriers to prevent unauthorized parking in emergency zones. Educate staff on the importance of keeping emergency routes unobstructed."],"revisedProbability":1,"revisedSeverity":3},{"id":86,"activity":"Security","hazards":["Unauthorized Access Theft of Equipment and Materials Vandalism or Sabotage Workplace Violence or Conflict Trespassing by the Public Fire and Arson Risk Poor Lighting and Surveillance"],"probability":4,"severity":3,"controls":["Install fencing and barriers around the site to prevent unauthorized entry. Implement controlled access points with ID verification for workers and visitors. Use security guards at entry/exit points to monitor access. Maintain a visitor log and issue temporary passes for authorized personnel. Secure tools, machinery, and materials in locked storage areas when not in use. Implement inventory tracking systems to monitor equipment movement. Use GPS tracking devices on valuable assets. Conduct random security checks on workers and vehicles leaving the site. Ensure adequate lighting in entry/exit points, storage areas, and blind spots. Establish a security control room for real-time monitoring of surveillance footage. Train workers on conflict resolution and de-escalation techniques. Establish a zero-tolerance policy for violence, harassment, or threats. Provide security personnel with communication devices to report incidents quickly. Conduct background checks on workers before hiring. Place warning signs around the site indicating restricted access. Install temporary fencing around excavations or hazardous areas. Regularly inspect the perimeter for gaps or weak spots in the fencing. Conduct routine security patrols to deter trespassers. Implement a fire watch system and ensure fire extinguishers are available. Train workers on fire safety procedures and emergency evacuation plans. Install fire alarms and suppression systems in key locations. Develop an emergency response plan to handle threats. Conduct security drills for evacuation and emergency response. Restrict access to high-risk areas of the site. Coordinate with local law enforcement for security planning. Provided Hot Line number to contact with local authorities in case of any emergency."],"revisedProbability":1,"revisedSeverity":3},{"id":87,"activity":"Waste Handling","hazards":["Manual Handling Injuries Exposure to Hazardous Waste Cuts and Puncture Wounds Fire and Explosion Hazards Biological Hazards Slips, Trips, and Falls Rodent and Pest Infestation Inhalation of Toxic Fumes Equipment and Machinery Accidents"],"probability":4,"severity":3,"controls":["Train workers on correct lifting techniques to prevent injuries. Use trolleys, wheelbarrows, or lifting equipment for heavy waste. Avoid overloading waste bins to reduce strain. Separate hazardous, general, medical, and recyclable waste in designated bins. Use color-coded waste bins to identify different types of waste. Ensure proper labeling of hazardous waste containers. Provide cut-resistant gloves, safety boots, face masks, and protective clothing. Require respiratory protection when handling chemical waste. Ensure eye protection when dealing with hazardous liquids or fumes. Store flammable waste separately in fireproof containers. Keep waste storage areas well-ventilated. Conduct regular fire risk assessments and provide fire extinguishers. Use sealed containers for organic and medical waste. Implement safe disposal procedures for contaminated materials. Provide hand-washing facilities and sanitizers to prevent infections. Ensure regular cleaning and waste collection to avoid clutter. Use anti-slip mats in areas prone to spills. Provide spill kits and train staff on how to handle leaks safely. Keep waste bins covered and emptied regularly. Implement pest control measures such as traps or repellents. Avoid leaving food waste exposed. Train workers on safe operation of compactors, crushers, and waste disposal trucks. Install safety guards and emergency stop features on machines. Ensure regular maintenance of waste-handling equipment."],"revisedProbability":1,"revisedSeverity":3},{"id":88,"activity":"Tipping Operation","hazards":["Vehicle Overturning Unstable Load Worker Struck by Moving Vehicles Slips, Trips, and Falls Mechanical Failures Dust, Noise, and Vibration Exposure Contact with Overhead or Underground Utilities"],"probability":4,"severity":3,"controls":["Conduct ground condition checks before tipping to ensure stability. Avoid excessive loads that can shift or cause imbalance. Always tip on level ground to prevent overturning. Use sideboards or barriers to prevent material spillage. Secure loads properly and distribute weight evenly. Lower the tipper bed gradually and smoothly. Avoid tipping in high winds or wet conditions that can cause instability. Define safe tipping zones and restrict unauthorized access. Use banksmen (spotters) to guide vehicles and prevent collisions. Implement high-visibility clothing and warning signals for workers. Mark and enforce pedestrian walkways separate from tipping areas. Keep tipping areas clean and free of obstacles. Provide non-slip surfaces or mats where necessary. Ensure proper lighting and signage around tipping areas. Perform regular maintenance and inspections of tippers. Check brakes, hydraulic systems, and tipping mechanisms before use. Keep emergency stop functions accessible and functional. Use dust suppression systems like water sprays. Provide operators with ear protection and dust masks. Limit working hours in high-vibration areas to reduce fatigue. Conduct utility checks before tipping near electrical lines or pipelines. Maintain safe distance clearance from overhead power lines. Use ground-penetrating radar (GPR) if tipping near underground utilities."],"revisedProbability":1,"revisedSeverity":3},{"id":89,"activity":"Material Delivery Vehicle","hazards":["Vehicle Collision (On-site & Off- site) Overturning or Loss of Control Unsafe Loading and Unloading Manual Handling Injuries Slips, Trips, and Falls Exposure to Dust, Noise, and Vibration Mechanical Failures (Brakes, Tires, Steering, Hydraulics) Reversing Accidents Fuel Spillage and Fire Hazards"],"probability":4,"severity":3,"controls":["Ensure trained and licensed drivers operate delivery vehicles. Enforce speed limits and proper traffic management plans. Use one-way routes where possible to avoid congestion. Install convex mirrors at blind spots to improve visibility. Secure loads with straps, chains, or nets to prevent shifting. Do not exceed weight limits or overload the vehicle. Use forklifts, cranes, or hoists to lift heavy materials safely. Train workers on proper lifting techniques. Provide lifting aids such as trolleys, pallet jacks, or forklifts. Encourage team lifting for heavy loads. Keep delivery areas clean and free of obstacles. Use non-slip surfaces or mats in high-risk zones. Provide proper lighting and signage. Provide high-visibility vests for workers near vehicles. Require safety gloves, boots, and helmets during loading/unloading. Use dust masks and ear protection in high-exposure areas. Conduct pre-use inspections (brakes, tires, steering, lights). Implement a routine maintenance schedule for all delivery vehicles. Use banksmen (spotters) to guide reversing vehicles. Install rearview cameras and reversing alarms. Ensure clear signage and designated reversing areas. Keep spill kits available for fuel leaks or chemical spills. Train workers on fire safety and emergency response. Ensure fire extinguishers are available in delivery vehicles."],"revisedProbability":1,"revisedSeverity":3},{"id":90,"activity":"Lifting Gear Handling","hazards":["Failure of Lifting Gear Incorrect Slinging or Load Attachment Manual Handling Injuries Struck by Swinging or Falling Load Slips, Trips, and Falls Entanglement and Pinching Hazards Electrical Contact (Overhead Power Lines)"],"probability":4,"severity":3,"controls":["Inspect slings, chains, and shackles before use. Ensure lifting gear is rated for the load capacity. Avoid shock loading by lifting smoothly and steadily. Remove damaged or worn-out lifting gear from service immediately. Train workers on correct rigging and hitching techniques. Use tag lines to control swinging loads. Ensure proper sling angles to prevent excessive stress on lifting gear. Do not exceed the safe working load (SWL) of the lifting gear. Use mechanical lifting aids whenever possible. Train workers on correct lifting techniques to prevent back injuries. Encourage team lifting for heavy lifting gear. Ensure loads are balanced and secured before lifting. Keep workers clear of suspended loads at all times. Stop lifting operations in high wind conditions. Keep lifting areas free of debris, oil, or water. Use anti-slip mats where necessary. Mark safe walkways and restricted lifting zones. Use gloves with good grip while handling lifting gear. Keep hands clear of moving chains and winches. Ensure workers are trained to recognize pinch hazards. Maintain safe clearance distances from overhead power lines. Use non-conductive lifting slings in electrical hazard areas. Conduct site inspections before lifting near power sources."],"revisedProbability":1,"revisedSeverity":3},{"id":91,"activity":"Carpentry Workshop","hazards":["Contact with Moving Machinery Manual Handling Injuries Flying Wood Chips and Debris Slips, Trips, and Falls Fire and Explosion Hazards Noise and Vibration Exposure Inhalation of Wood Dust and Fumes Electric Shock and Faulty Equipment Hand Tool Injuries"],"probability":4,"severity":3,"controls":["Install safety guards on saws, planers, and other machinery. Use emergency stop buttons and kill switches on all machines. Train workers on safe operating procedures and lockout/tagout (LOTO) practices. Train workers on proper lifting techniques. Use lifting aids (e.g., dollies, trolleys) for heavy materials. Encourage team lifting for large or awkward items. Provide safety goggles or face shields when using cutting or sanding equipment. Enforce mandatory PPE use in all tool operation areas. Regularly clean up sawdust and debris to prevent slips and fire hazards. Use non-slip mats and clearly mark walkways. Secure or cover loose cables to avoid tripping. Install a dust extraction system to minimize wood dust build- up. Store flammable chemicals in fireproof cabinets. Keep fire extinguishers and alarms accessible and in working order. Provide hearing protection (earplugs or earmuffs) for noisy tasks. Use anti-vibration gloves for prolonged tool use. Rotate tasks to limit exposure time to loud or vibrating tools. Install local exhaust ventilation (LEV) for dust and fume extraction. Provide dust masks or respirators for tasks generating fine particles. Regularly inspect and maintain ventilation systems. Conduct routine electrical inspections of all tools and wiring. Use ground-fault circuit interrupters (GFCIs) for added protection. Train workers on electrical safety procedures. Ensure sharp tools are kept in good condition to reduce excessive force injuries. Provide tool-specific training for safe handling and proper usage. Store tools in a designated area to avoid accidental injury."],"revisedProbability":1,"revisedSeverity":3},{"id":92,"activity":"Steel Banding and cutting operation","hazards":["Cuts and Lacerations Injuries from Flying Metal Fragments Manual Handling Injuries Slips, Trips, and Falls Impact and Crush Injuries Noise Exposure Inhalation of Metal Dust and Fumes Electrical and Fire Hazards"],"probability":4,"severity":3,"controls":["Wear cut-resistant gloves when handling steel bands. Use safety goggles or face shields to protect against flying metal fragments. Provide hearing protection in high-noise areas. Ensure Strictly Follow (Hard Hat, Safety Shoes Hand Gloves, Safety Goggles and High Visibility) as per ADOSH SF CoP 2.0 – Personal Protective Equipment. Use respirators or dust masks in areas with metal dust exposure. Wear safety boots with steel toe caps to protect against dropped materials. Always use banding tools rather than cutting steel bands manually. Cut away from the body to avoid injury from recoiling bands. Use long-handled cutting tools to maintain a safe distance. Secure bands before cutting to prevent sudden release of tension. Keep floors clear of loose banding to prevent trips and falls. Store cut bands immediately in designated disposal area. Ensure good lighting for visibility during operations. Use lifting aids (hoists, forklifts, or trolleys) for heavy steel bundles. Train workers on proper lifting techniques to prevent back injuries. Encourage team lifting for large or awkward materials. Rotate tasks to limit exposure to high-noise levels. Conduct regular noise monitoring to ensure compliance with exposure limits. Inspect cutting equipment regularly for faults or wear. Keep electrical cables and tools in good condition to prevent shocks. Ensure emergency stop buttons are functional and accessible. Train workers on safe operation procedures for cutting machines."],"revisedProbability":1,"revisedSeverity":3},{"id":93,"activity":"MEWP Operation","hazards":["Falling from Height Overturning or Tipping Over Collision with People or Objects Electrical Contact Mechanical or Hydraulic Failure Falling Objects Unauthorized or Untrained Operators Slips, Trips, and Falls on Platform"],"probability":4,"severity":3,"controls":["Operators must wear a full-body harness with a lanyard attached to an approved anchor point. Ensure guardrails and toe boards are intact and secured. Avoid sudden movements that could destabilize the platform. Only operate MEWPs on firm, level ground—use stabilizers when necessary. Never exceed the maximum load capacity of the platform. Do not use in strong winds (above manufacturer’s limit) or extreme weather conditions. Use a trained spotter when operating in congested areas. Ensure pedestrian exclusion zones are marked with barriers and signage. Conduct a 360-degree check before moving the MEWP. Maintain a safe distance from overhead power lines (minimum 3m/10ft unless insulated). Use insulated MEWPs when working near live electrical sources. Inspect electrical components and cables before use. Conduct daily pre-use checks of brakes, hydraulics, tires, emergency controls, and safety features. Report any faults immediately—do not use defective equipment. Follow manufacturer-recommended maintenance schedules. Use tool lanyards to secure tools while working at height. Keep materials and equipment secure within the basket. Establish no-go zones below the MEWP during operation. Only certified operators should use MEWPs. Provide regular training on safe operating procedures. Maintain a log of authorized operators for accountability. Keep walking surfaces clear of tools, debris, or spills. Ensure non-slip flooring is intact. Use two hands on guardrails when moving within the platform."],"revisedProbability":1,"revisedSeverity":3},{"id":94,"activity":"New or expectant Mother","hazards":["Display Screen Equipment Lifting and Carrying Loads Slips, Trips & Falls Fatigue Welfare Out of hours working Work Related Stress Temperature / Humidity Access / Egress Biological or Chemical Serious incident"],"probability":3,"severity":3,"controls":["Ensure new and expected mothers must be given awareness training about mental health and changes in the human body. Ensure new and expected mother should not wear high heels shoes. Ensure wheelchairs must be available in every office for emergency situation. Workstation should provide adequate adjustment to allow for increase in abdominal size. Advice on posture to prevent musculoskeletal problems. Reduce the amount of physical work associated with tasks. Physical tasks become more difficult to achieve as pregnancy progresses Carrying heavy loads to be avoided. Maintain high standards of housekeeping in the work area. Individuals may have difficulty negotiating stairs during the later stages of pregnancy. Provision of easy access to toilet facilities a n d m o r e frequent breaks from work activity Consideration should be given to providing access to quiet areas where the individual can rest as necessary. Avoid long periods of time standing. Task modified to provide seating or more frequent rest periods. Aspects of the work may need to be modified as physical capability will be reduced as a result of pregnancy. Monitoring & reduction of risks in relation to work demands, relationships with colleagues / line manager and requirements of the role. Temperature of the working environment to be suitably controlled. Individuals may require access to fresh air for periods during the working day. Individuals have ready access to fresh drinking water. Allowance made for tiredness and nausea at early stages of pregnancy. Consult with occupational health and individual on modification to working hours / avoidance of out of hours working. Seek to modify the individuals work task to avoid walking significant distances or traversing flights of steps. New or Expectant mother must not be exposed to biological or chemical agents. Consider alternative tasks to working environment where exposure is recognized"],"revisedProbability":1,"revisedSeverity":3},{"id":95,"activity":"Office Equipment, Such as Printer, Shredder Etc.","hazards":["Entanglement Noise Contact with rotation part. Exposure to electrical risk (Faulty connections, poor cable management, etc.) Serious injury"],"probability":3,"severity":4,"controls":["Read and comprehend the manufacturer’s instructions on the hazard risk and safety controls that shall be adhered prior to using office equipment. Be aware of any “Warnings/Caution/Danger” listed on the office equipment and adhere to the precautions accordingly. Avoid skin contact and inhalation when handling photocopier toner cartridges. Use caution when using sharp cutting instruments. Provide adequate ventilation as recommended by the manufacturer to dissipate any hazardous ambient condition. Chemicals (such as those used for printer cartridges, etc.) shall be supplied with a Safety Data Sheet (SDS) - follow all instructions for safe use, handling and storage. Only use suitable appropriate stepladders and stepstools for reaching height. Do not use revolving chairs or other unsafe means to gain height. Under no circumstances should any member of staff attempt to repair any electrical connections or photocopying equipment Ensure the use of appropriate electrical appliances. Regular inspection shall be undertaken for all electrical equipment such as PAT (Portable Appliance Test) & internal inspection by competent personnel and tagging provided. Do not overload electrical power points and plugs. All electrical outlets and receptacles shall be tested and tagged. Use only approved electrical appliances. All electronic cabling, sockets, and lighting to be maintained to high level (insulating tape, broken plug tops, loose sockets etc. are unacceptable). Never use bare wire connections. No cabling shall be allowed to run across open floor space. Staff must be trained and advised to report defective plugs or cables to the responsible person and should not repair them themselves. Keep loose clothing away from office equipment to prevent entanglement. Regular periodic servicing must be carried out for photocopiers by the service provider. Staff shall not bring their own electrical appliances without prior approval from the concerned facility management concerned or designated competent personnel. Lockout/Tagout (LOTO) procedures and permit to work shall be implemented while working with live electricity."],"revisedProbability":1,"revisedSeverity":3},{"id":96,"activity":"Hygiene and Welfare (Canteen, Pantry and Designated Rest/Eating area)","hazards":["Exposure to Infection and illness due to unhygienic workplace."],"probability":3,"severity":3,"controls":["Kitchen/Pantry to be provided with drinking water (Hot and Cold), fridge and cleaned daily.","Regular disposal of waste & garbage to prevent pest infestation or breeding.","Canteen must be managed by certified catering company with all relevant authorities’ approvals/NOC. Canteen personnel must have attended ADFCA training and hold a medical fitness certificate.","Daily cleaning and disinfection of the office, pantry, and canteen facilities, importantly for high/frequently touch surfaces must be carried out.","In order to discourage vermin, food must not be consumed or left in public or undesignated areas.","Toilets to be supplied with hot water, soap, hand wash liquid and tissues."],"revisedProbability":1,"revisedSeverity":3},{"id":97,"activity":"Display Screen Equipment / Workstation","hazards":["Ergonomic Hazard Musculoskeletal disorder, Eye Strain /visual fatigue Upper limb pains and discomfort (WRULD’s – Work Related Upper Limb Disorders) due to Repetitive task. Strain Injury"],"probability":3,"severity":3,"controls":["Ensure all the department head/ line manager must evaluate / assess their respective teams workstation and facilitate safe and ergonomic workstations accordingly.","Workstation and display screen equipment shall be set to ensure good posture to avoid glare and reflections on the screen. Visual fatigue can be caused by poor quality screens. Screen image should be stable, clear (acceptable brightness and resolution)","An adjustable chair with arm rest must be provided and used. The person’s back while sitting must be in a relaxed, upright position, with the backrest of the chair adjusted to provide good lumbar support. Use footrest for comfort as deemed necessary.","Train all employees on the recognition of potential hazards, risk and strains and the best working postures/procedures.","Ensure all employees take a break on a short frequency (e.g., very 30 minutes) and stand up from their workstation, in order to move them body or stretch to regularize their blood circulation.","A big screen/monitor must be provided to minimize the use of laptop with small screen as per the nature of the work.","Use window blinds provided to control ambient light and screen reflection/glare.","Ensure the computer screen is positioned at the right level, angle and height to eliminate or minimize glare onto the screen.","Workstation must be sufficient of size for work and provide enough room to allow the employee to work.","When using a mouse keep the arms level and the angle of the wrist to a minimum.","Remember, as a general rule the things that are used the most should be kept close to the user to prevent overstretching.","The immediate work environment should have sufficient space and an appropriate level of lighting.","Temperature and humidity values must be maintained at optimum levels.","Noise levels should be monitored and assessed accordingly.","Move the chair close enough to the desk so that the keyboard can be reached out comfortably.","Should always ensure there is enough room in front of the keyboard to rest the wrists and hands during pauses at work. When keying, keep the forearms horizontal and reduce the angle of the wrists to a minimum.","Take adequate breaks to prevent continuous working and overexposure to screens: and ensure to do basic stretches and exercises to mitigate any risk to whole body due to musculoskeletal fatigue. Avoid sedentary work positions to avoid health issues."],"revisedProbability":1,"revisedSeverity":3},{"id":98,"activity":"Use of Ladders","hazards":["Failure to ensure 3 points contact. Unsecured ladder Ladder not positioned at correct angle. Ladder not extending one meter above the landing surface. Falls from Height - Back Injury, Fractures, Cuts, Bruises, Death. Falls of Materials – Head Injury, Death, Fractures, Cuts, Bruises Slipping/Collapse - Back Injury, Fractures, Cuts, Bruises, Death."],"probability":3,"severity":4,"controls":["Ladders/step ladders shall be manufactured to EN or equivalent standards. Fabrication of ladders on site is not acceptable and they shall be removed.","Ladders/step ladders are often unstable, outriggers may be required, or an additional worker must foot and steady the ladder.","Never use straight ladder for carrying any task from height. Only use step or podium ladder.","Ladders must be inspected weekly and colour coding must be in place.","Maintain Ladder register with inspection status.","Ladders must only be used for short duration light work and inspection, with one hand on the ladder as a minimum at all times. If this cannot be done another work platform is required","For working with live Electrical work, use Wooden /insulated ladder only.","Ladder must extend 1m beyond platform, at 75- degree angle or 4:1 Height to Base ratio.","Ladder must be placed on firm level base.","All ladders must be adequately tied (not by styles) to a fixed sound structure.","Tools should be secured to worker by tool bag/tool belt or lanyard. Damaged ladders must be destroyed.","Hard Hats worn especially below ladder.","If over 9m landing platform must be provided.","Only one person on ladder at one time. Top three steps of the ladder shall not be used.","Materials to be hoisted up or carried in tool bag.","Three points of contact to be maintained at all times.","Ladders never to be used close to a leading edge, ladders to be kept at least one and a half times the ladder length away from a leading edge."],"revisedProbability":1,"revisedSeverity":3},{"id":99,"activity":"Night Works or out of working hours","hazards":["Poor visibility resulting in personnel coming into contact with plant, equipment, etc. Lack of concentration resulting in an accident. Slips, trips and falls"],"probability":3,"severity":4,"controls":["Night work procedure shall be developed, communicated, and implemented.","Workers who are working in the night shift must have adequate breaks.","During all night works competent supervision must be on site to supervise the works.","All work areas are to be suitably lit for works with artificial lighting.","Lighting towers to be in place and checked by the Supervisor to ensure they are in good working order prior to the work commencing.","Working in night-time conditions will make it more difficult to see dips or potholes or other obstructions on the haul road, therefore, the speed limit should be reduced.","Ensure ground conditions where the operatives are working are as level as possible, remove tripping hazards.","Headlights on vehicles/plant must be in good working condition and cleaned regularly during night work as any dirt on the lenses will greatly reduce visibility.","Poor weather conditions will increase the danger of working during dark conditions as visibility and site conditions will be poor. Weather forecast to be checked in advance of the works by the Construction Team to ensure it is suitable to proceed.","Ensure that lighting used does not interfere with public traffic or be located in such a manner that it blinds vehicle drivers, crane drivers or riggers on site.","All plant to have flashing beacons which are to be switched on and in good working conditions.","Lifting operations will be kept to a minimum during the night shift. Required lifts will be completed during the day in preparation for the night shift where possible e.g. positioning of piling frame. Lifting operations which will be carried out at night will include lifting the piling hammer, pitching tubular piles, etc.","Riggers and operatives must be visible at all times. It is important that they have clean hi-visibility vests.","Riggers to be issued with torches to improve their visibility and to allow them to give clear signals to drivers.","Task Notification process shall be developed, and the PMC and Consultant shall be notified of the type of activity with the resources in place to manage and supervise the task safely."],"revisedProbability":1,"revisedSeverity":3},{"id":100,"activity":"Plant and Equipment:","hazards":["Plant and equipment falling into the excavation or trench."],"probability":3,"severity":4,"controls":["Effective planning and JSA is essential prior commencing nay excavation work, regardless of the depth or dimension of the excavation or trench.","Provision of rigid barricades such as concrete barriers, etc. around the excavation during and after the digging process.","Soft barricades around the excavation should be avoided.","Simultaneous activity within the proximity of the excavation shall be prohibited. Moreover, any equipment being operated other than the digging equipment shall be assessed, and suitable precautions taken as deemed necessary, such as, appropriate demarcation zone to be provided with signage to caution the adjacent activity.","The operators of plant and equipment shall be retrained to be aware of the importance of ensuing situational awareness while working in the site, thereby look out for any potential hazard such as excavation, etc. in order to prevent the risk of being falling into such excavation.","The operator shall be fit for duty and must undergo periodic health assessment as mandated by law and project specific risk assessment.","All the plant and equipment shall be facilitated with competent banksman in order to guide the safe maneuvering and reversing operation of the equipment.","Periodic inspection regimen and close level of competent supervision is vital to avoid any accident."],"revisedProbability":1,"revisedSeverity":3},{"id":101,"activity":"Collapse of column (stiffener) structural element: Collapse of In-situ Column due to struck by plant and equipment","hazards":["Collapse of structural element due to hit by equipment.","Serious or fatal injury","Property damage."],"probability":3,"severity":4,"controls":["Adhere to the approved structural design and drawing for the safe erection of stiffener column. Any changes to work at site shall be coordinated with the competent structural engineer and accordingly the design shall be revised and updated.","Erect the column to its fullest in such a manner to prevent any free- standing structure.","The starter bar for column construction shall be of appropriate size and dimension as per the approved drawing specification and in the case of new dowel then it shall be inserted using suitable bonding epoxy chemical into the ground slab and secured using approved material.","Appropriate supports (such as robust prop jacks, etc.) shall be facilitated to ensure the stability of the stiffener column and thereby preventing any inadvertent collapse.","Avoid operating any construction vehicle or equipment beside the newly constructed column or that which is not fully supported from both the bottom and atop."],"revisedProbability":1,"revisedSeverity":3},{"id":102,"activity":"Construction Hazards at Project During Site Visit by ALDAR Employees (*Note: Since Most of The ALDAR Employees Are Not Performing Any Type Of Construction Activities Except Office Job So They Must Not Be Directly Exposed To Below Hazards): A. Heat Stress B. Excavations C. Access to Scaffolds / Ladders D. Noise & Vibration E. Substances Hazardous to Health F. Confined Spaces G. Temporary Electrical Supplies H. Working at Height I. Expectant Mothers J. Office Safety K. First Aid L. Driving M. Falling Material N. Working Over Water","hazards":["Note: The risk to ALDAR employees is low as we have office staff at managerial level,","Fatality,","Serious illness / injury","serious dangerous occurrence,","property damage"],"probability":4,"severity":4,"controls":["Many of below recommendations are not applicable to ALDAR employees as ALDAR does not perform the task but assign PMC, Consultant and Main Contractor approved by ADOSH-SF & adequate OSH resources are available in each project e.g. PMC/Consultant OSH representative & Contractor OSH team etc. all ALDAR employees are working from office based and if they visit any construction site they are visiting an area which is under the control of main contractor.","Comply with Project specific OSH Plan and procedure as per Consultant and Contractor requirements and advise.","ALDAR employees shall follow the project requirements and must not perform any task on site other than advising the parties involved to comply with the contract, process and scope of work.","Shall attend Contractor OSH induction conducted at the project prior to working on a project.","Follow the heat stress program implemented in each project.","Never intentionally enter an unsafe situation or participate in an unsafe activity.","Wear appropriate mandatory PPE’s, such as safety shoes/boots, high visibility vest, Safety goggles, and hard hat at all times or as per project requirements once visit the site under the control of consultant and main contractors.","Avoid using cell phones on site except in project office and in designated safe zones.","ALDAR visitors shall sign the visitors log and shall be accompanied at all times.","All staff and visitors shall be familiar with site specific emergency procedures and contacts as per main contractors approved documents, resources, and requirements.","Full compliance with specific approved method statement and risk assessment for each particular activity.","Pregnant members of Staff working on the project shall report to HR for a further assistant and specific RA shall be completed by PMC, & Contractor (As applicable).","For pregnant and expected mothers, ensure that hours of work and the volume and pacing of work are not excessive. Ensure that seating is available where appropriate. Longer or more frequent rest breaks must help to avoid or reduce fatigue. Adjusting workstations or work procedures may help remove postural problems and the risk of accidents. Manual Handling Training and re-instruction should be considered. Where necessary the nature of the work carried out may need to be addressed to reduce the amount of physical work carried out or aids provided to help reduce the risk.","Any work that requires ALDAR staff to wear safety harness / lanyard, must not be undertaken until a task specific risk assessment and method statement has been completed by contractors. Users of harnesses must receive adequate training. Any unsafe situation must be reported to the PMC & Consultant OSH representative along with OSH TEAM (QHSE) team, as soon as practicable.","Only enter confined spaces if all control measures are put in place by consultant and contractor and safe to do so if the employee is competent otherwise it is not allowed (Very rare) i.e. ensure third party certifications to all entrants, approved Method Statement, risk assessment, Job Safety Analysis and permit to work system is in place.","It is not anticipated that ALDAR staff will be exposed to substances hazardous to health. However, in the event that hazardous substances must be used the measures described in the RA should be followed.","All electrical DBs and Sub-DBs shall be provided with a suitable RCD 30 mA and an approved Single Line Diagram (SLD) must be posted.","No ALDAR staff must be exposed to live electrical supplies such as use of power tools, cables, DB’s etc.","No ALDAR staff must be exposed to noise above the action levels however staff are advised to wear hearing protection (ear plugs available with the project Health & Safety Department) if they go to noisy areas.","ALDAR staff must only enter excavations when necessary to do so and when appropriate safety control measures have been put in place by the consultant and contractor.","While driving at site, adhere to site speed limit and vigilant with adjacent moving equipment & operatives, and park the vehicle at designated place.","Only use scaffold if required and if it is provided by contractor and approved by consultant if it is safe & Scaff tag system is implemented. No personnel shall not work near open edges or holes in the slab and must leave the area immediately. The unsafe situation must be reported to PMC and Consultant OSH representatives as soon as practicable.","Suitable life jackets with appropriate rescue arrangements shall be in place prior to work adjacent to the water.","Any Occupational incident including near miss shall be reported to the concerned PMC and Principal contractor for further investigation and process as per the project approved incident management protocol and in line with ALDAR OSH MS – Appendix 17 requirements."],"revisedProbability":1,"revisedSeverity":4},{"id":103,"activity":"Earth Cutting by Mechanical Equipment (JCB, Dozer, Shovel, Etc.)","hazards":["Unsafe positioning of","Instability of equipment","Presence of ground staff in the equipment movement area","Dust generation","Moving through uneven level ground","Equipment colliding each other Property damages.","Failure of equipment stance","Equipment colliding w","Unsafe earth edges without physical edge protections leading to vehicle or personal fall into the pit/trench.","Cave in of earth over the equipment Air pollution","Lack of banksman","Fire hazard due to faulty electrical connections"],"probability":4,"severity":4,"controls":["Equipment operators with valid UAE license, third party certificate and adequate experience in the site shall be deployed. Health assessment as per ADOSH-SF Requirement.","Underground utility survey shall be carried out prior to commence any soil cutting or excavation to prevent any damage.","If any utility identified within the vicinity should be marked and obtain adequate permit from the relevant authority prior to exposing the service or continuing further.","All the banksman/flagmen shall be provided with distinguishable and unique coloured coverall and PPE’s in order to easily distinguish them, as well as red & green flag to be used during assisting and guiding the plant and equipment. Flagmen shall stand at safe location for example, at least 10 meters away from the equipment/ plant/ trucks. Flagmen shall always maintain good eye contacts with the Operator/ Drivers and vice versa.","Position equipment at strategic locations by maintaining adequate operational distance; for example, exceeding minimum 15 meters between each other.","Area supervisor shall always ensure the equipment’s swing radius/area is not interacting other adjacent equipment or structure.","Back-hoe excavator must be positioned on firm ground to attain good stance prior to start the cutting works.","No personnel shall be assigned in the equipment movement areas/danger zone.","Earth bunding must be created around the location being cut, prior to start the operation.","All deep excavations should be provided with hard barricades to prevent fall of person or toppling of equipment.","‘Deep Excavation’ signage must be installed in the physical edge protection to alert the hazard. Water sprinkling in the haul roads for reducing the dust generation.","Loading of earth/soil from excavator and shovel buckets to the trucks must be at the least possible height.","Adequate slope/shoring/shielding must be ensured in the sides of the excavations (based on the soil type and approved cross section drawing) to prevent cave in.","Adequate supervision must be ensured to ensure the safe operational ground for every equipment.","All plant equipment operators should competent and having valid training records.","All personnel shall wear site mandatory PPE. (Safety shoes, coveralls, safety helmets, high- visibility jackets)."],"revisedProbability":1,"revisedSeverity":4},{"id":104,"activity":"Operating Heavy Machineries, plant and Trucks for Earth Moving Works","hazards":["Incompetency of the Operators/ drivers","Frequent reversing & forward movement of plant/ equipment/ trucks","Presence of ground staff (pedestrian) close to equipment","Operators’ slip/ fall from equipment/ plant while getting in/ out.","Blind spot of the equipment/ trucks","Use of blinders/shades/ stickers on the view screen of the operator cabin.","Substandard electrical wiring or connections, causing fire.","Serious Personal Injuries.","Property Damage"],"probability":4,"severity":4,"controls":["Remove the defective equipment as soon as the defect is found.","Excavation permit to work (combined services drawing) shall be complied by the Site Engineer.","Ensure all plant & equipment’s should be fitted with safety devices/features such as but not limited to, reverse alarm, rear view mirrors, brake lights, hazard warning lights, revolving lights, Safe Load Indicators (Lifting equipment’s) etc.","Periodical water sprinkling to be carried out for dust suppression at construction sites and haulage roads.","All the banksman/flagmen shall be provided with distinguishable and unique coloured coverall and PPE’s in order to easily distinguish them, as well as red & green flag to be used during assisting and guiding the plant and equipment. Flagmen shall stand at safe location for example, at least 10 meters away from the equipment/ plant/ trucks. Flagmen","shall always maintain good eye contacts with the Operator/ Drivers and vice versa.","Stipulated site speed limit must never be exceeded. Any deviation shall be dealt with stringent action.","Switch off the engine & apply hand brakes when machine is not working or operator not in operating seat.","Always Park the equipment/ plant/ trucks in the designated area without obstructing the access route.","Operators shall be instructed for not to carry workers in the machine unless the additional passenger seat is provided with safety belt.","Equipment/ plant/ truck daily checklist inspection shall be completed by the Operator.","Instruction to the operators & drivers to avoid engine idle and shutdown the engine when not in use/operation.","Assign competent Foreman to supervise the activities at site.","Occupational health surveillance for all designations must be carried out on regular basis as per ADOSH-SF requirements.","Roll over protections system (ROPS) and fall over protection system (FOPS) must be equipped with the equipment.","Grade checker, Flagman, ground staff, etc. must be inside their designated protected point (barricaded points) while monitoring the operations.","Toolbox talk training by Site Engineer with Foreman, Drivers, Operators and Flagmen.","All plant & equipment electrical wiring should be as per manufacture recommendation and regulations; provision of any additional substandard wiring/joints should be prohibited.","All equipment should be facilitated with portable fire extinguisher and must be inspected on monthly basis.","All plant & equipment cabins should be free from unwanted accumulations to prevent fire hazard.","Regular preventive maintenance program for all plant & equipment shall be carried to prevent any accidental break-down or failure of equipment."],"revisedProbability":1,"revisedSeverity":4},{"id":105,"activity":"Electrical Substation (Accessing and carrying out inspection or task)","hazards":["Unauthorized access into the substation.","Unguarded cable trench Unauthorized removal of floor grating","Lack of access to enter the cable trench.","Falling of personnel into the cable trench – Serious injury"],"probability":3,"severity":4,"controls":["Safe operating procedure shall be established detailing the mechanism to enter and perform any task inside the sub-station.","Regardless of energized or deenergized, the substation shall be controlled via lock and hazard warning signage posted.","PTW system shall be instigated along with all the necessary safety","control measures in place to access and carryout any task.","Cable trench opening shall be primarily protected with hard barricade and thereupon until the steel gratings are installed these barricades shall not be removed.","Safe means of access/egress shall be facilitated to enter the cable trench.","Soon after the installation of the grating, if for any reason these have to be removed then PTW system shall be ensured along with alternative controls around the openings to prevent accidental fall of personnel.","Use of loose planks or protection cover over the trench opening shall be avoided. Rigid means of protection shall be facilitated.","Regular OSH training is vital, including information and instruction along with competent supervision to enable and monitor the safe work system is fully adhered."],"revisedProbability":1,"revisedSeverity":3},{"id":106,"activity":"Electrical System (Temporary or Permanent)","hazards":["Procurement of substandard electrical distribution equipment and accessories.","Unsafe / unstable electrical distributions and fittings.","Installation or extension of electrical distribution by incompetent persons.","Damage to trailing cables – Electrical.","Unsafe connections / splicing- Electrical.","Lack of routine inspection and maintenance- Electric System.","Electric shock leading to injury or fatality.","Electrical fire","Burns due to flashover","Property damage."],"probability":4,"severity":4,"controls":["Electrical components and accessories (distribution boards, switches, fuses, circuit breakers, cabling, sockets and splitters) shall be manufactured to UAE safety standards (Refer ADOSH SF – CoP 15.0 – Electrical Safety, Electrical Wiring Regulations 2020), EN (European Norms) or equivalent e.g., ANSI (American National Standards).","Ensure to select correct RCD type (AC/A/F/B) as per load characteristics and manufacturer instructions (e.g., EV chargers, PV inverters, VFDs).","All equipment’s and power tools should be inspected and tagged (Based on condition) for purpose by a competent person prior to delivery to the site and use to ensure the function of electrical components to protect the workforce from electrocution hazards such as RCD (30 mA), Earthing, Isolator, Voltage regulator, IP rated DB’s, suitable wiring, appropriate industrial sockets etc.","All defective equipment’s and power tools should be tagged as “Don’t use” and should be removed from project stores.","Project requirements, load bearing and required outputs shall consider prior to the procurement of electrical appliances.","Ensure the purchasing of electric appliances with inbuilt trip/safety devices. Design out portable extension leads where practical (install fixed outlets near the work).","A Competent Electrician Engineer shall design the temporary distribution system in line with expected loading requirements. Accordingly, Single Line Diagram (SLD) for the electrical system to be developed and approved.","Never use site made fabricated panel board using wooden timber and plywood. Only approved IP (Ingress protection) rated panel board with suitable strand shall be used.","Only competent electrician to complete any electrical works on site. No person shall be permitted to work as an electrician until valid certification is provided to the competent Electrical Engineer.","Circuit protection shall be built into the design and suitable circuit breakers installed in all distribution boards. The standard rating for RCD shall be 30 mA tripping rate.","Periodic documented inspections for the electric system shall be performed by a competent electrician.","Use standard applications and connection methods (Industrial sockets with flap covers) for the electric connections.","Ensure periodic monitoring/ surveillance by an assigned electrician to avoid unauthorized operations.","All operations shall be monitored and controlled by competent electrical supervisor.","Armoured cabling shall be used for principal distribution where there is a risk of damage to the cable sheath. Cables crossing roads shall be armoured and protected/buried.","Cable hangers and cable stands shall be utilized on construction sites to elevate trailing cables and provide additional protection from damage or water ingress where feasible. Ensure and follow proper cable management. Secure/ elevate/ burry the cable always (If possible).","Cables shall not be extended or repaired through cut and splice. Only industrial cable connectors or joint kits shall be used.","Where transformers are used to step down voltages, the competent engineer and site electricians shall ensure that all transformers are inspected before use and included in the periodic inspection program.","All electrical leads/cables to be inspected and colour coded.","The Periodic documented inspection shall be performed by the competent electrician.","A record of inspection shall be retained, and a signature sheet/tagging shall be attached to each board to allow for immediate verification. Ideally, PAT (portable appliance testing) shall be carried out. Power tools shall be clearly marked to show that they have been inspected in line with the current inspection program. This may be by PAT labels or through the use of colour coded tape as per approved project schedule/monitoring program.","All electrical hand tools shall be inspected by competent person on monthly basis, tagged/ colour coded, and records maintained. Only inspected tools shall be used.","All electrical DB output sockets should be provided flap-covers to protect water ingress.","All Distribution Boards (DB’s) and Diesel Generators (DG’s) should be provided with individual earthing and impedance test shall be carried on periodical basis & records to be maintained.","While using power tools ensure the handler body should be in dry condition and strictly prohibited to handle any electrical activity in wet body condition (such as during summer).","Ensure all final electrical DB’s should be near the workplace for adequate identification and to turn-off power during contingency situations.","Ensure earthing/loop impedance: verify ohm values and bonding to ensure disconnection times are within code limits.","Ensure enclosures to IP rating appropriate for location; temp/humidity as per manufacturer.","All metal body power tools should be properly body earthed and bonded to prevent any electric leak.","Ensure all electrical cables should be as per required load and rating; All wires (for example Phase, neutral and Earthing) should be connected firmly at required areas (at sockets/power tools/DB etc).","Ensure safe isolation (LOTO), permit to work for live testing, use of portable tools, temporary power setup.","Ensure periodic verification using an RCD tester in line with legal requirements.","Ensure rescue stick availability at testing & commissioning area to handle any rescue personnel.","Ensure to ground the bus bar after isolation of power to discharge any dead energy.","All portable Air conditioners should be inspected by competent person on periodical basis and never use domestic socket or substandard provisions.","Pre use inspection of portable RCD adaptors/cord sets and tools","remove damaged units.","Ensure electrical rated gloves and arc rated PPE for testing/commissioning as required by arc flash and shock risk","assessments."],"revisedProbability":1,"revisedSeverity":3},{"id":107,"activity":"Elevator Entrapment- (Including Passenger Hoist)","hazards":["Faulty elevator","Failure hoist structure.","Adverse weather impacts","Lack of maintenance","Serious injury","Property damage"],"probability":3,"severity":3,"controls":["The building Facility Management along with the Security Team and ERT Team are responsible for the rescue arrangement for issues related to elevators. Clear instructions must be displayed in each elevator along with an emergency button for immediate reaction. Third party tests along with regular maintenance shall be undertaken for all elevators. Push and hold the alarm button located on the control panel as per posted instructions in case of any emergency. The SWL or no. of person allowed at a time should be marked inside the lift. The overload alarm/sensor should be tested periodically and conduct periodically preventive maintenance as per regulatory/manufacture recommendations. When the security officer responds, speak clearly providing the following information: Location of Floor as indicated in the display screen. Number of personnel trapped inside the lift. Any medical condition of those trapped within the lift. Follow instructions given by the security officer. Do not attempt to break or open the doors as this may delay your exit. Don’t use the elevator during emergencies such as fire and explosion, etc."],"revisedProbability":1,"revisedSeverity":3},{"id":108,"activity":"File Cabinets","hazards":["Fall of cabinet","Hit by open cabinet door.","Filing cabinet tripping over.","Crush injury","Serious injury","Property damage"],"probability":3,"severity":4,"controls":["The cabinets should be positioned on an even surface and adjacent to the wall to provide adequate support.","Don’t pull the cabinets forcefully to prevent slip and fall hazard or exerting force that might cause sprain or strain injury.","Ensure contents are distributed evenly with heavier documents in the lower drawers. Don’t overload the cabinets.","Open one cabinet at a time - slow and easy.","Close all cabinets when finished and not in use.","Filing cabinets should be loaded from the bottom up to maintain stability.","Cabins with damaged parts or hinges should be replaced with new materials to prevent accidental fall."],"revisedProbability":1,"revisedSeverity":4},{"id":109,"activity":"Erection of Formworks, Walls and Columns.","hazards":["Collapse of False work","Injury of operatives during erections/striking","Falls of operatives during erection/striking","Falls of Materials","Back injury from manual handling","Shutters falling scaffold.","Lifting operations","Contact with scaffold.","Work from ladders","Hand Injuries v.08/ May-2025"],"probability":4,"severity":4,"controls":["All work to be completed is under the guidance and control of the Temporary Works Co- ordinator and permit to work system should be implemented precisely.","A formwork system should be selected that can have a working platform attached to it and assembled on the ground and lifted into position. Establish safe sequence of erection and dismantling of the formwork. PTW for both loading (loading of huge loads such as steel rebar bundle, concreting, etc.) and permit to strike (after the concrete attains its required strength) shall be implemented.","Ensure platform is such that workers will not have to stand on top of shutter when pouring concrete.","Ensure Tie rods are highlighted and protected using mushroom caps.","Ensure there is adequate space to maneuver concrete skip.","Use a MEWP or mobile tower scaffold to work from if adjustments to the formwork are to be made at a height. The same systems can then be used for pouring.","If for some reason adjustments must be made outside the confines of the working platform a full body harness and lanyard must be worn and securely attached to a secure anchorage point","Care and attention in the use of tools.","Ensure adequate and safe working platforms (e.g. columns, beams, lift shaft activity) to prevent any overreaching/unsafe approach by the employees.","All external formworks should be performed by using suitable and safe working platform.","Avoid using long ladders for access and work at height activity.","Avoid using incomplete platforms or unsecured loose planks.","Ensure to implement exclusion zones underneath working at height area and restrict personnel entry by placing hard barricades.","Ensure suitable fall protection arrangements such as Self Retractable Lifeline (certified)/ temporary lifeline arrangements during formwork installation and until installation of full guardrail system.","All temporary lifelines shall be installed away from the exposed and anchored on suitable place, inspected and certified by competent personnel prior to use it.","Ensure safe means of access/egress points with overhead protection wherever required.","Place robust catch nets or overhead protection at required places to prevent fall of materials.","Scaffold system to be erected, dismantled or adjusted by competent certified scaffolders only.","Scaffold to be signed off as safe to use by a competent certified scaffold inspector prior to use.","Raker beams to be erected to the scaffold system.","Scaffold to be dismantled prior to lifting the shutter when striking.","Banksman to ensure the area is clear of all personnel prior to the commencement of the lifting operations.","Banksman to ensure chain is in a straight position prior to the shutter being lifted by the crane operator.","Lift plan to be completed by trained and certified lifting coordinator.","Taglines to be in place at all times during lifting operations.","Rigger to ensure no persons work under or near a suspended load.","Good communication to be maintained at all times during the lifting between rigger and crane operator.","Crane operations to be suspended during adverse weather conditions based on manufacturers specifications.","Three points of contact to be maintained on ladder if used for hooking/Unhooking lifting gears.","Ladder to be footed at all times when in use.","Flagging system to be implemented to indicate the hazard and the personnel permitted to access and carryout the task on the formwork."],"revisedProbability":1,"revisedSeverity":3},{"id":110,"activity":"General Access Scaffold","hazards":["Fall from Height - Back Injury, Fractures, Cuts, Bruises, Death","Fall of Material -Head Injury, Death, Fractures, Cuts, Bruises","Collapse - Back Injury, Fractures, Cuts, Bruises, Death"],"probability":3,"severity":4,"controls":["Scaffold general design shall be done by competent structural/design engineer.","Obtain valid Scaffold Erection and dismantling PTW before commencing the task.","Only third-party certified scaffolders shall be permitted to erect/alter or dismantle scaffold with full-time supervision.","Perform prestart briefing to the entire workforce whose are involved in the activity.","Adequate ties and raker or supporting tower must be provided as per the design to ensure the stability of the scaffold tower.","Scaffold must be inspected prior to use /weekly/ when altered and Scaff tagged.","Firm Level base to be used, with suitable access/ egress.","Double handrail with the top handrail erected with the gap between the toe board and mid guard rail and the mid and top guard rail to not exceed the approved dimension as per legal requirements.","Toe boards should be no less then 150mm (as per legal requirements)","No overloading with materials."],"revisedProbability":1,"revisedSeverity":3},{"id":111,"activity":"Lone Working","hazards":["Injury or ill health while working alone in the office.","Lack of communication arrangements","Slips, trips and falls","Violence and aggression","Sudden illnesses/health issues/ incident."],"probability":3,"severity":3,"controls":["Lone work should be minimised or avoided where feasible.","Specific Lone Working Risk Assessment may be required in circumstances where any potential risks are increased (e.g. expectant mothers, persons with mobility issues or medical conditions).","Provision of first aid arrangements to employee working alone.","Means of communication shall be established between the lone worker and the supervisor.","The workstation must be controlled and monitored by CCTV.","Full time 24/7 security system, electronic access pass provided for all employees and visitor to control and account the number of employees.","Employees shall be trained to determine and handle any potential violence situations in a safe manner.","Frequent monitoring of personnel deployed alone and getting information on their status.","Emergency plan shall be developed to tackle any violence or aggression for lone workers.","Women alone working shall not be permitted after working hours unless permitted by the supervisor or line manager."],"revisedProbability":1,"revisedSeverity":3},{"id":112,"activity":"Lifting Operation, Mobilization/ Construction Works.","hazards":["Slips, trips and falls.","Impact/hit by crane.","Mechanical failures to lifting gears and lifting appliance.","Hitting nearby structures or existing under- ground/overhead services.","Collapse /fall of crane due to poor soil bearing capacity.","Working in bad weather.","Site Traffic accidents","Fire hazard to the crane due to substandard electrical connection or presence of spark.","Injury to site personnel from","Falling objects or materials.","Damage to vehicles or property during","lifting operations. Risk from suspended loads","Failure of brake and/or mechanical parts of plant.","Bypassing SLI can lead to collapse of lifting equipment.","Serious injury to person.","Damage to property.","Fatality v.08/ May-2025"],"probability":3,"severity":5,"controls":["Project Specific Lifting plan along with risk assessment shall be developed and PTW system for lifting operations must be implemented. All the involved personnel shall be communicated of the approved Safe system of work and process.","Strict adherence with the authority circular pertaining to lifting equipment & accessories and monthly compliance shall be carried out.","Ensure periodical Inspection / certification of crane & lifting accessories by the third party & assure serviceability of crane. Planned preventive maintenance shall be carried out for the lifting equipment and records maintained.","Ensure operator is competent, trained & having valid license.","Ensure competent Rigger appointed to give signal & the competency is certified by 3rd party.","Tower crane erection/installation/dismantling shall strictly adhere with the safety requirements as mandated by the authority (Crane foundation as per approved structural calculation, maintenance regime by approved third party, operator and rigger trained by the supplier or manufacturer, etc.).","Ensure radio communication between signal man & operator as deemed based on the assessment.","Ensure proper coordination between lifting supervisor / crane operator / rigger (signal man)","Check overhead clearance for swing the boom and any existing structure.","Competent Supervisor / Foreman / Rigger shall carry out task under the supervision of lifting appointed personnel.","Lifting radius and the crane shall be appropriately barricaded and signposted.","Lifting equipment shall not exceed the crane working limit (SWL) and manufacturer’s recommended SWL.","The crane operator shall not use the SLI bypass system during lifting to overreach and strict preassessment & planning shall be carried to ensure safe erection.","All limit switches (Anti-Two block, Anti-Collision Device, limit switches (Tower crane trolley etc.), boom limit switch, SLI etc.) and safety features (Anemometer, etc.) shall be checked on regular basis and ensure its working condition and must avoid bypassing the critical safety devices.","Before release of sling belt tie, on the trailer bed check the stability of stacked material & unload the material in sequence wise.","Ensure crane capacity, lifting radius as per tonnage. Use tested & certified lifting tackles and protect the sling with appropriate packing.","Sling shall be placed at the Center of Gravity (CoG) of the lifting load and use tag line of adequate length to control swing movement.","Ensure while slinging, the load shall not be allowed to slung & hit with adjacent material to avoid sliding & falling of material/object.","Always keep the access walkway clear to avoid tripping hazard.","Carry out lifting operation as per load charts & ensure proper coordination between Crane Operator, Rigging Supervisor & Signal man.","Provision of anti-collision system if more than one tower crane is used and there is likelihood of overlapping of boom or lifting wire. Also, if there are any adjacent structure whereby the tower crane could accidentally hit then anti-collision must be installed accordingly.","During adverse weather condition the tower crane boom shall be not locked (i.e. weather vane (free- slewing) to be active) to prevent impact to the crane boom.","Ensure lifting equipment and tackles are inspected and tested (including proof load test) by authority approved third party.","Restrict the personnel movement around swing radius, display signage & with proper barricading. Tag line to control swing movement during operation","Adequate competent supervision and strict prohibition of two-tier working system or simultaneous operation.","Inspection of soil bearing capacity before placing the crane.","Daily and periodic crane inspection shall be carried out by both the crane operator and lifting appointed personnel and inspection records shall be maintained.","Periodic maintenance must be carried out for the crane and if the crane is more than 15 years old then NDT (Non-Destructive Test) test must be carried out (Note: Reference must also be made to the manufacturers specification and legal requirements).","Stop operation in blind spots /congested locations. For long load based on the risk assessment use spreader bar or beam to distribute the SWL.","Aware of overhead power lines and under-ground utilities.","Provide adequate traffic diversions or traffic managements when lifting operations are carried on public roads (NOC and approval from concerned authority must be obtained prior working on public road).","Segregation of pedestrian/other workers from the lifting operation area with necessary safety barricades, warning sign boards and flag man as required.","Check the ground condition before mobilizing the crane. Ensure the out riggers are fully extended. Do not place the crane too close to the excavation.","Ensure all lifting operation is carried out under competent supervisor. Follow the weather forecast and stop operation during high wind / poor visibility.","Operator must consider the bad weather conditions like sandstorm, fog, heavy wind (if wind speed exceeds 38 KMPH or as per lifting risk assessment/JSA, manufacturer specs and legal requirements, the lifting operation shall be ceased).","Do not drive the crane on the construction site without signalers/Banks man.","Do not park the crane on the vehicle moving area without making an exclusive zone.","Do not use any opaque material on the side glasses of the crane which may cause obstruction for operator’s vision.","Provision of appropriate PPE / Toolbox Talk & Pre-Task briefing and ensure compliance of personnel.","All electrical fittings should be as per manufacture guidelines and recommendations to avoid any spark or short-circuits.","The operator cabin should be free of unwanted accumulations and diesel tank area should be free of flame source."],"revisedProbability":1,"revisedSeverity":3},{"id":113,"activity":"Personal Protective Equipment (PPE)","hazards":["Lack of available personal safety equipment & PPE or Working without PPE.","Lack of training in the use of personal safety equipment & PPE.","Poor quality / substandard personal safety equipment & PPE.","Failure of PPE leading to personal injury or long-term health problems","High incidence of head, eye, hand and foot injuries e.g. cuts/lacerations, abrasions, penetrating wounds, eye injuries, impact wounds etc."],"probability":3,"severity":3,"controls":["The required volume of personal safety equipment and personal protective equipment (PPE) shall be specified at the procurement stage. Sufficient spares shall be always maintained in the site.","Personal safety equipment and PPE shall be maintained and replaced if damaged or in line with manufacturers recommendation life cycle.","Personal safety equipment and PPE requirements for specified works shall be detailed in the project OSH plan, method statement risk assessment (MSRA) and reinforced through toolbox talks and training.","Personal safety equipment and PPE discipline shall be paramount and disciplinary action taken against those failing to comply.","Site employees shall be trained in the use of personal safety equipment and PPE through onsite training and toolbox talks. Training shall include both the use and purpose of the protective equipment.","Employees shall be provided with personal safety equipment and PPE at no cost to themselves and shall be provided with replacement protective equipment on an old for new basis. Employees shall not be required to utilize old or damaged protective equipment in order to reduce costs.","Some PPE e.g., hard hats and high visibility vests are colour coded to allow easy identification of trades. Riggers / Signallers / Banksman will wear a red hard hat for example.","Minimum PPE requirements on site are Safety helmet, Hi-visibility vest, safety footwear with steel toecaps (Coverall for workers).","The standard of personal safety equipment and personal protective equipment (PPE) shall be specified at the procurement stage. Personal safety equipment and PPE shall be manufactured to EN (European Norms) or equivalent standard e.g. ANSI (American National Standards). Protective equipment shall carry an identifying symbol to confirm conformance, alternatively, conformance certification shall be made available at the project.","Personal safety equipment and PPE failing to meet these standards shall be removed from the site.","Safety shoes to be worn properly and fully tied.","Any tampering or non-wearing of PPE will lead to disciplinary actions."],"revisedProbability":1,"revisedSeverity":3},{"id":114,"activity":"Machine Guarding - Sand Sieving/Screening Machine","hazards":["Unprotected rotating parts of conveyor belt assembly.","Serious or fatal injury","Property damage."],"probability":3,"severity":4,"controls":["Premobilization of all the plant and equipment is essential to ensure all the safety devices are in good condition and the equipment is fit for the","task. Tagging system to be put in place to indicate the condition of the equipment.","The inspection regimen shall take into due consideration all the necessary safety requirements pertaining legal and reference to be made to the manufacturer manual to adhere with the specific inspection program as detailed in the manual.","All the rotating parts of the plant and equipment shall be guarded adequately and in the case of equipment without full protection for the exposed parts then suitable guard to be retrofitted in such a way that it will not introduce any additional hazard or risk to the operatives.","Never allow the removal of any protective guards which will endanger the safety of the operatives.","Establish and implement suitable Permit to Work System and lock out tag out system while carrying out any repair or servicing and such task only to be performed by competent operatives.","Periodic inspection by competent personnel is essential to determine any deficiency and if so immediate actions to be taken or the equipment shall be taken out of service until repaired and rendered as safe to use.","Periodic preventive maintenance by competent personnel is vital to ensure the equipment is safe and sound.","Operatives involved in the operation shall be competent. Along with close level of competent supervision & monitoring."],"revisedProbability":1,"revisedSeverity":3},{"id":115,"activity":"Pressure Testing","hazards":["Explosion/Burst of pressurized pipes/conduits.","Ejected materials & fittings.","Leakage of hazardous substances.","Fatality or serious injury/illness."],"probability":3,"severity":4,"controls":["A formal pressure testing procedure must be prepared, communicated, and implemented accordingly.","PTW system shall be implemented prior commencing the task.","Leak testing must precede testing.","Testing must be planned at the lowest pressure acceptable to specification and should be avoided unless there are sound technical reasons for carrying out the tests.","Access to the test equipment and the adjacent area is to be restricted.","Pressure test gauges must be correctly dated to ensure correct calibration. Fire protection and first-aid equipment must be available before testing begins.","Task specific PPE, such as goggles and gloves must be available.","Vulnerable items such as meters and pressure switches must be removed.","Access equipment must be provided as necessary to enable easy access to the controls to be gained.","Only authorized, experienced and competent persons must carry out pressure testing.","This must be controlled, preferable by a permit to work system.","The manager or supervisor must carry out an inspection of the system before starting to test, to ensure that isolations, blanks, and other specified safety devices are in place before any testing begins.","All operatives must be briefed on the hazards, precautions, and emergency procedures, before testing starts.","If a permit system is used, they must also be trained in the permit procedure and actions required by the system.","Regular OSH toolbox talk safety training including daily pre-task briefing shall be conducted prior the task commencement."],"revisedProbability":1,"revisedSeverity":3},{"id":116,"activity":"Road Transport On Site","hazards":["Poor road condition.","Blind curve.","Overturning","Collision with pedestrians/operatives","Collisions with structures","Collision with other vehicles","Causing collapse of or falling into excavations","Restricted vision due to traffic route corners","Site service cables","(surface)","Excessive Speed.","Fatality or serious injury."],"probability":3,"severity":4,"controls":["An approved Traffic management plan must be in place.","Traffic management plan must be reviewed regularly and amended.","The site must be surveyed, and vehicle routes planned to avoid danger to pedestrians, contact with buildings, structures, or overhead power lines, and to be clear of excavations.","Vehicles must be subject to a planned maintenance programme.","Restricted visibility at junctions and corners must be addressed by placing reflective mirrors or traffic lights especially on large heavy trafficked sites.","Lighting to be placed on all traffic routes during part of winter months and when night work is to be carried out.","On sandy/dusty, a dust suppression schedule to be agreed and implemented, on contaminated sites provision & use of a washing down point to prevent heavy mud or dust being dispersed by vehicles leaving site onto the local highway.","Suitable fencing must be provided around excavations.","Barriers and notices must be erected at overhead power lines. Vehicle operating areas and traffic routes must be clearly signed and fenced off where practicable. Stop boards must be fitted to excavations where tipping is to take place.","Drivers must ensure loads are placed evenly in vehicles and that the vehicle is not overloaded.","Drivers must not remain in or on vehicles being loaded.","Tipping vehicles must not move with the body raised and stop boards must be used to prevent over-run of edges.","Those intended for use on the public highway must comply with current licensing requirements.","Signs requesting visiting vehicle drivers to report to the site office must be displayed.","Speed restrictions must be displayed and enforced, as necessary.","Competent banksman must be provided with all the equipment and traffic marshals at identified road junctions and accident-prone locations to be deployed.","Visiting drivers must be briefed on site rules and hazards.","All employed and contractors’ drivers must hold a current driving license and must be trained in site and plant safety awareness. In general, visiting drivers must wear the minimum standard PPE safety helmet and safety boots."],"revisedProbability":1,"revisedSeverity":3},{"id":117,"activity":"Use of Angle Grinder","hazards":["Entanglement Long hair, loose clothing, rags, cleaning brushes and jeweler could become entangled in the moving parts of the equipment.","Impact and cutting The mobile exposed moving disc presents a risk to an operator’s hands and body parts.","Potential for disc to fragment on use.","Inappropriate accessories used on the angle grinder may result in the disintegration of the disc or work piece being ejected","Electricity Damaged or frayed electrical cords would pose an electrical hazard.","Noise Operation of the plant equipment can result in high noise levels.","Friction Friction injuries may occur from contact with grinder disc","Sips/trips/falls Poor housekeeping allowing the build-up of waste materials or failure to immediately clean up spills could result in a slip hazard.","Fire Sparks created during the grinding process may become an ignition source if flammable material is in the immediate vicinity (e.g. flammable liquids, wood dust, rags).","Temperature Work piece and grinding wheel may get hot with continuous use"],"probability":3,"severity":4,"controls":["Pre-mobilization inspection for all the portable power tools must be carried out by competent personnel along with tagging/colour coding.","Always select the correct rated disc for the tools, ensure the RPM (Rotation Per Minute) disc/grinder wheel must be greater than the RPM of the power tools.","Make sure the disc’s expiry date is imprinted on the disc and use only those discs with valid date.","Make sure that hair, loose clothing, rags and jewellery are kept clear of moving parts when in use.","Aprons to be used to restrict loose clothing entanglement.","Make sure jewellery and accessories (e.g. bracelets) are not worn when operating equipment.","Make sure operator hands and body parts are kept clear of moving grinding disc during operation and maintenance.","Make sure operator checks the disc prior to use for flaws or cracks.","Make sure that appropriate discs are used for specific tasks.","Operator to check for damaged electrical cords prior to use.","Make sure equipment is serviced on a regular basis, tested & tagged.","Appropriate hearing protection should be worn whilst operating this equipment.","Make sure appropriate cleaning & housekeeping standards are always maintained to minimise the risk of a slip, trip or fall.","Make sure the angle grinder is not used near flammable materials and good housekeeping practices are maintained.","When cutting materials containing stones, rocks, clays, sands (Concrete, Kerbing, Paving, blocks etc.), which produces Respirable Crystalline Silica, an adequate suitable dust mask must be worn.","Do not use grinding wheel continuously.","Allow grinding wheel and work piece to cool prior to handling.","All power tools and machineries with rotating machine parts must be fitted with guards.","Only industrial sockets shall be used for all electrical connections.","Ensure that only compatible parts or fixtures are procured and used as per manufacturer’s specification.","Approved risk assessment shall be communicated to all team members via toolbox talks.","All electrical hand tools shall be inspected by competent person on monthly basis, tagged/colour coded, and records maintained. Only inspected tools shall be used.","Ensure that the right tool is used for the activity.","Ensure that the parts or fixtures are changed by authorized person only.","Never remove /fix disc while the tool connected to the power source, isolate the tool before the disc removal/tightening.","Ensure the use of double eye protection (eye protector with a face shield) while performing with abrasive wheels.","Consider adjacent workgroup while operating tools with abrasive wheels, never allowed adjacent activity/operatives.","Adequate supervision shall be provided."],"revisedProbability":1,"revisedSeverity":3},{"id":118,"activity":"Use of Gas Welding And Cutting Equipment","hazards":["Fire and explosion","Cylinder Explosion","Inhalation of toxic fumes","Asphyxiation","Injury to eyes","Burns","Risk to Third Parties from sparks and fumes"],"probability":3,"severity":5,"controls":["Hot work Permit to work system along with JSA must be implemented for the task and all the checklists shall be duly adhered. Pre-start planning must consider the location of welding and cutting work, fire safety/prevention needs, materials to be worked, available ventilation, other works in progress in the area, local site rules and statutory requirements.","Gas cylinders shall be stored at designated locations away from combustible/flammable area and firefighting arrangement shall be facilitated. Fuel and oxygen cylinders shall be stored with safe distance in place. Hazard warning signage shall be posted.","All work to be planned in advance, taking account of the above.","Suitable screens and fire blankets must be readily available to protect flammables and persons from sparks and heat.","Where ventilation is poor, local exhaust ventilation must be provided.","The minimum numbers of gas cylinders must be kept at the workplace, and these must be upright and secured.","Flashback arrestors must be fitted to all gas regulator sets and at the torch.","All necessary fire prevention equipment, and fire extinguishers, must be in place prior to the commencement of work.","Flash back arrestors must be fitted both at the nozzle and cylinder regulator valve.","No work must take place in areas, where the presence of flammable or explosive substances is suspected without specific assessment, or the area and any containers to be cut are certified as `Gas Free`.","Competent fire watch must be detailed where there is an assessed significant risk of fire or heat transfer to adjacent areas.","A check of the work area must be carried out by the fire watch (for at least 30 minutes or based on the risk assessment) after completion of the shift or the work for any possibility of latent fire hazards, including smouldering.","All the personnel involved in the activity including supervision staff shall be trained.","Personnel shall use task specific PPE, such as gloves, boots, overalls, aprons, eye protection, etc.","Pre-task safety briefing on daily basis is essential for all the involved workforces."],"revisedProbability":1,"revisedSeverity":3},{"id":119,"activity":"Work related stress","hazards":["Physical Factors - Fatigue and exhaustion","Job Demand/pressure including tight deadlines","Job role/level of competency or training to perform the responsibility - Insufficient training for job responsibilities","Inexperienced or unqualified workers handling complex tasks.","Organizational Change","Frequent changes in management or project scope","Unclear communication of new policies and procedures","Mental stress and burnout","Reduced job performance and decision-making capacity"],"probability":3,"severity":4,"controls":["Implement proactive stress management programs.","Provide adequate training programs and refresher courses","Clear job descriptions and role assignments","Mentorship and supervision for new employees","Training to identify potential signs and symptoms of stress and actions to be taken","Transparent communication regarding changes","Support programs for employees during transitions","Employee engagement and feedback mechanisms","Clear and transparent communication of any organizational or other changes that might affect employees.","Proper workload distribution and realistic deadlines","Encourage breaks and promote a supportive work environment","Provide mental health support and stress management programs","Conflicting job demands to be assessed, ensuring only a practical workload to prevent fatigue or stress"],"revisedProbability":1,"revisedSeverity":3}];
if (typeof window !== 'undefined') window.RISK_REGISTER = RISK_REGISTER;
if (typeof module !== 'undefined' && module.exports) module.exports = RISK_REGISTER;
